/* Book: On the Path of Love from Morocco to Jerusalem */
var BOOK_HTML = "<div class=\"book-section\" id=\"book-content\">\n    <h2 class=\"book-main-title\">על שביל האהבה ממרוקו לירושלים</h2>\n    <p class=\"book-subtitle\">פרלה ופנחס בן הראש | הוצאה לאור: 2014</p>\n    <p class=\"book-p\" style=\"text-align:center;font-style:italic;color:var(--c-gold);font-size:.85rem;margin-bottom:1rem\">שַלַּח לַחְמְךָ עַל־פְּנֵי הַמָּיִם, כי בְּרֹב הַיָּמִים תִּמְצָאֶנּו — קהלת (יא, א)</p>\n    <div class=\"book-nav\" id=\"book-nav\">\n      <button class=\"book-nav-btn active\" onclick=\"document.getElementById('book-prologue').scrollIntoView({behavior:'smooth',block:'start'})\">פרולוג</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch1').scrollIntoView({behavior:'smooth',block:'start'})\">א': שורשים באדמת מרוקו</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch2').scrollIntoView({behavior:'smooth',block:'start'})\">ב': מעגל השנה</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch3').scrollIntoView({behavior:'smooth',block:'start'})\">ג': מרוקו של ילדותי</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch4').scrollIntoView({behavior:'smooth',block:'start'})\">ד': כמיהה ציונית</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch5').scrollIntoView({behavior:'smooth',block:'start'})\">ה': אל הדרור</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch6').scrollIntoView({behavior:'smooth',block:'start'})\">ו': ימים ראשונים</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch7').scrollIntoView({behavior:'smooth',block:'start'})\">ז': סיפורה של פרלה</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch8').scrollIntoView({behavior:'smooth',block:'start'})\">ח': בית ומשפחה</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch9').scrollIntoView({behavior:'smooth',block:'start'})\">ט': במדים</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch10').scrollIntoView({behavior:'smooth',block:'start'})\">י': המבט לעבר</button>\n    </div>\n    <div class=\"book-chapter\" id=\"book-prologue\">\n      <h3 class=\"book-ch-title\">פרולוג</h3>\n      <p class=\"book-ch-page\">עמודים 5-6</p>\n      <p class=\"book-p\">הייתי אז ילד קטן. אימא הייתה אתנו בבית, ואבא עבד בכמה עבודות כדי להביא פרנסה הביתה. לעת ערב הייתה אימא משכיבה אותי ואת אחיי הקטנים לישון במיטותינו, ורק מאוחר יותר היה אבא מגיע, נכנס בשקט הביתה, וממיטתי הייתי מדמיין את החיוך שחייך לעבר אימא. יכולתי גם לדמיין את האור שנדלק בעיניה. אחר כך היו יושבים שניהם ליד השולחן במטבח, אימא הייתה מגישה לו ארוחת ערב, ולאחר שהשביע את רעבונו, אבא היה מספר לה סיפורים. אז הייתי מתכרבל היטב בשמיכה ומטה אוזן. לחלק הזה חיכיתי.</p>\n      <p class=\"book-p\">\"את יודעת,\" שמעתי את אבא אומר ערב אחד לאימא, \"האגרטל הזה שאת מחזיקה ביד, הוא עתיק מאוד\" בעיני רוחי ראיתי את אימא עומדת שם ובידה האגרטל, אולי העבירה אותו ממקום למקום, ואולי רק הרימה אותו כדי לנקות את האבק שנח על הארון שתחתיו. \"שליתי אותו מספינה שנטרפה בים, אז, מזמן, כשעבדתי כאמודאי\". שנים לפני שנולדנו עבד אבא כאמודאי (מעין צוללן), בחברה אמריקנית שאספה אוצרות, שנותרו על ספינות שטבעו בים.</p>\n      <p class=\"book-p\">\"נדמה לי שלא סיפרתי לך על הפעם ההיא שבה כמעט וקיפחתי את חיי שם\" אמר אבא, וידעתי שבאותו הרגע שכחה אימא מהאגרטל, התיישבה לצדו והביטה בו, כשהיא מרוכזת בו לחלוטין. גם אני, ממיטתי, נשאבתי כל כולי אל תוך הסיפור.</p>\n      <p class=\"book-p\">\"היינו יורדים אז למעמקי הים, אל אניות שנטרפו ותרים אחר אוצרות שנותרו בהם. הסתובבנו שם למטה זמן רב, בוחנים את החפצים שטבעו במעמקים, ספונים בין החדרים, מחפשים רק את אלו שהיה בהם ערך\" אבא סיפר והאנייה הלכה והתגלתה לנגד עיניי, על המבנה הגדול והמרשים שלה, קורות העץ המרקיבות מרוב שנים במעמקי הים ולהקות הדגים שהפכו אותה לבית. רטט של עונג ומתח עבר בגבי.</p>\n      <p class=\"book-p\">\"באותו היום,\" המשיך אבא בסיפורו, \"ירדתי אני אל המעמקים. האמודאי שתפקידו היה להוריד אותו מהספינה ולהעלות אותי חזרה, נשאר על מקומו בסיפון. סמכתי עליו שכאשר אסמן לו, הוא ימשכני למעלה. ירדתי בצלילה למטה, בחנתי את שברי הספינה הטרופה שהייתה שקוע בעומק הים, ובחנתי את כל מה שיכול היה להיחשב כאוצרות יקרי ערך. לא רציתי להעלות אתי למעלה חפצים חסרי-ערך ולהיות ללעג וקלס בעיני חברי לעבודה. לפתע הרגשתי שאיני יכול לנשום עוד, וזמן קצר לאחר מכן, מתוך ערפול חושים, הרגשתי איך אני נמשך מן המים מעלה אל הסירה, ומושכב על הסיפון. כשהתאוששתי מעט ניגש אליי הקברניט ואמר לי: 'בן-הרוש, בזמן שהיית בתוך המים, הלך עבדול אל הכבלים שהחזיקו אותך למטה, וכשחשב שאף אחד לא רואה - חתך לך את צינור האוויר. למזלך הוא רק חשב שאף אחד לא ראה אותו, אבל הפועל הקטן שלנו, מחמוד, ראה אותו ורץ אליי להודיע לי, ואני הוריתי לשני אנשים לקפוץ אחריך ולהביא אותך.' ואז, המשיך אבא בסיפורו: 'וכבר אני שומע את הקברניט אומר לי: שנהרוג אותו? ואני נחרדתי כולי, חשבתי שלא שמעתי נכון את דבריו. מה? שאלתי אותו, והקברניט חזר ואמר: עבדול, ניסה לרצוח אותך בזמן שהיית במעמקים! רק תגיד מילה ונהרוג אותו.'\"</p>\n      <p class=\"book-p\">אבא עצר לרגע, אולי כדי לנשום, אולי כדי להרטיב את גרונו ואני התכווצתי במיטתי במתח.</p>\n      <p class=\"book-p\">\"לא היססתי לרגע ואמרתי לו: 'לא. תפטר אותו.'\"</p>\n      <p class=\"book-p\">ושוב יכולתי לנשום. אך עד מהרה התברר כי הסיפור עדיין לא נגמר.</p>\n      <p class=\"book-p\">\"יום אחד, חודשים מספר לאחר מכן, יצאתי רכוב על סוסי לעבר הנמל, לעבודה. לאחר שיצאתי מן העיר אל המרחבים שבחוץ, זינקו עליי שני ערבים שארבו לי במקום, כיסו את ראשי בשק וקשרו אותי לעץ. חיכיתי שם זמן מה. מרגיש איך החמצן שבשק הולך ואוזל, חרד כי סופי הגיע, וחושב על משפחתי ומי יודיע להוריי על שאירע... ואז שמעתי הלמות פרסות סוסים מרחוק. עד מהרה עצר לידנו מישהו. הוא נותר על הסוס ואני יכולתי להרגיש את מבטיו סורקים אותי מכף רגל ועד ראש. שוביי פנו אליו ואמרו לו 'תפסנו איזה כלב, בן יהודים מלוכלך'. 'לפני שאתם מדברים תורידו את השק, אני רוצה לראות אותו' הוא אמר להם קצרות. השק הוסר מעל ראשי, ואני שוב יכולתי לנשום. אבל עוד בטרם התרגלו עיניי לאור השמש, שמעתי אותו צועק עליהם: 'אתם הכלבים, האיש הזה הציל אותי ממוות, שחררו אותו מיד!'. מצילי היה לא אחר מאותו עבדול, שרק חודשים מספר קודם לכן ניסה להרוג אותי כשהייתי בתוך הים...\"</p>\n      <p class=\"book-p\">אימא ודאי נשמה לרווחה אז, וכך גם אני, מרפה את גופי הקטן שהתכווץ מרוב פחד וחרדה. הייתה לאבא יכולת מופלאה לספר סיפורים שהחזיקו אותנו במתח עד לשנייה האחרונה ממש, ובעת שסיפר יכולתי להרגיש את כל אותן תחושות שתיאר.</p>\n      <p class=\"book-p\">\"שלח לחמך על פני המים כי ברב הימים תמצאנו\" סיכם אז אבא במילותיו של החכם באדם, כותב מגילת קהלת, \"עשה טוב ותמצא טוב.\" ועל אף שאבא לא היה לצדי באותם הרגעים, אלא דיבר עם אימא, הרגשתי איך האהבה, הדאגה וחכמת החיים שלו מרחפות לעברי מבעד לדלת ועוטפות אותי, ושינה מתוקה יורדת עליי.</p>\n      <p class=\"book-p\">שנים רבות חלפו מאז, אך הסיפור הזה ממשיך ללוות אותי ולהיות נר לרגליי. פעמים רבות אני חוזר במחשבותיי אל אותה אמרה שהנחתה אותי בדרכיו של אבא: 'עשה טוב ותמצא טוב'.</p>\n      <p class=\"book-p\">היום, כמו אבא בשעתו, אני צולל כאמודאי אל מעמקי הזמן והמרחב ושולה מהם את אוצרות עברי; את המקומות בהם הייתי, האנשים שלצדם חייתי והאירועים שעברו עליי בשמונים ושש שנותיי ועשו אותי למי שאני.</p>\n      <p class=\"book-p\">אני עושה זאת למענכם משפחתי האהובה - אשתי וחברתי היקרה, ילדיי, נכדיי וניניי היקרים, למען תדעו גם אתם מאין באתם, ושתמיד תאיר הדרך את פניכם.</p>\n      <p class=\"book-p\" style=\"text-align:left;color:var(--c-gold-d)\">פנחס בן הראש, ירושלים, 2013</p>\n    </div>\n    <div class=\"book-chapter\" id=\"book-ch1\">\n      <h3 class=\"book-ch-title\">פרק א': שורשים באדמת מרוקו</h3>\n      <p class=\"book-ch-page\">עמודים 7-18</p>\n\n      <h4 class=\"book-sub\">טנג׳יר של העולם הגדול</h4>\n      <p class=\"book-p\">שלושה-עשר קילומטרים מפרידים בין ספרד האירופאית ומרוקו הצפון אפריקאית. שלושה-עשר קילומטרים בלבד, טנג׳יר (Tanger), העיר המרכזית באזור, שוכנת בפתחם של מיצרי גיברלטר, בנקודת המפגש שבין הצפון והדרום, הים התיכון והאוקיינוס האטלנטי. עבור מעצמות אירופה הקולוניאליות במאות הקודמות, ובעיקר בעיני שלטונות ספרד הנושקת למרוקו, היה זה פיתוי שאי אפשר לעמוד בפניו, והאזור כולו עבר תהפוכות שלטוניות רבות כאשר פעם שלטו בו הספרדים ופעם האנגלים, פעם הפורטוגזים ופעם הצרפתים. טנג׳יר היפיפייה שאווירה מתירנית שלטה ברחובותיה וחופיה היפים משכו תיירים מכל רחבי אירופה, הייתה במשך מאות שנים מקום ריכוז לדיפלומטים, קונסולים ומרגלים זרים, ושימשה לא אחת כתפאורה לסרטים שאווירה מיוחדת שלטה בהם, ושעסקו במפגש בין המזרח והמערב, טנג׳יר אף הייתה לערש הולדתה של משפחת אמי ומשפחתי שלי.</p>\n\n      <h4 class=\"book-sub\">בית אימא</h4>\n      <p class=\"book-p\">אמי רינה, הייתה בתם הבכורה של סימי ויהודה קארו והראשונה בין ששת ילדיהם. אחריה נולדו אחיותיה: אסתר, מסודי, לונה ומזלטו, ובסוף, איזקה. הסבא יהודה קארו, המיוחס לרבי יוסף קארו ומגיע ממשפחת רבנים, היה אדם דתי, אך לא עשה את התורה למרכז עיסוקו, והתפרנס ממסחר בחיטה, שעורה ומזון יבש. לסבא לא היו גידולים משלו, הוא רק סחר בהם. שמו יצא לפניו כסוחר טוב והגון, והוא עשה חיל בעבודתו וראה פרות בעמלו. בבית סבא יהודה וסבתא סימי, שררה רווחה כלכלית. הם התגוררו בבית גדול ומרווח בן שתי קומות, משרתות מקומיות טיפלו בתחזוקת הבית וסייעו לסבתי, שהבית היה מרכז עיסוקה.</p>\n      <p class=\"book-p\">אמא גדלה בטנג׳יר בסביבה מוסלמית-ספרדית, ברחובות שלטה השפה הספרדית. באזורים בהם התגוררו יהודים אפשר היה לשמוע גם את הלדינו היהודית, וזו הייתה שפת האם של אמי.</p>\n\n      <h4 class=\"book-sub\">רבי יוסף קארו</h4>\n      <p class=\"book-p\">רבי יוסף קארו (1488-1575) הוא מגדולי הרבנים ופוסקי ישראל בכל הדורות, מחבר ה\"שולחן ערוך\" וה\"בית יוסף\", ועסק גם בקבלה. נולד בספרד ונאלץ לנדוד עם הוריו בעקבות גירוש ספרד. עבר מליסבון לקושטא, חי בבית דודו בטורקיה, והתבסס באדריאנופול. בהיותו בן 34 החל בכתיבת חיבורו על הטור. התאלמן, התחתן שוב, והקים ישיבה בניקופול שבבולגריה. עלה לארץ ישראל וקבע מושבו בצפת. לספר הקיצור שסיכם את הלכות ה\"בית יוסף\" קרא \"שולחן ערוך\" — ספר מרכזי ואבן יסוד בהלכה היהודית עד היום.</p>\n      <p class=\"book-p\" style=\"font-size:.8rem;color:rgba(237,224,196,.5)\">מקורות: ויקיפדיה, אתר דעת</p>\n\n      <h4 class=\"book-sub\">בית אבא</h4>\n      <p class=\"book-p\">אבי, שמואל בן הראש, יליד 1886, גדל גם הוא במרוקו הספרדית, בכפר הדייגים אסילה (Asilah) הסמוך לטנג׳יר. משפחתו של אבא הייתה קטנה מזו של אימא. להוריו, איטו לבית בן-אוליעל ויעקב בן הראש, נולדו שני בנים - שלמה הבכור, שמואל אבי, ושתי בנות - חולה (שם החיבה שלה היה רחל) שנפטרה בספרד בשנת 1947; ואסטריה (אסתר), שבשנת 1947 עזבה את מרוקו, היגרה לברזיל ומשם עקרה לארגנטינה.</p>\n      <p class=\"book-p\">אבא שייך אף הוא לשושלת מכובדת של רבנים, ומיוחס להרא\"ש - רבנו אשר בן-יחיאל, שהיה מגדולי פרשני התלמוד והפוסקים, והייתה לו השפעה מכרעת על עיצוב ההלכה היהודית, ובנו - רבי יעקב בעל הטורים.</p>\n\n      <h4 class=\"book-sub\">הרא\"ש ובניו</h4>\n      <p class=\"book-p\">הרא\"ש, הוא רבנו אשר בן יחיאל (1250-1327), נולד בגרמניה. אמו נהרגה על קידוש ה׳ באחת מהגזירות באשכנז. אביו יחיאל שהיה מחסידי אשכנז, היה מחנכו הראשון. למד אצל המהר\"ם מרוטנבורג, ומשזה נאסר, ירש את מקומו בהנהגת וורמס. בשנת 1304 מצא שעת כושר, עזב את גרמניה וברח עם בני ביתו לספרד. הזמינוהו ראשי קהילת טולדו להתיישב בתוכם, להרביץ תורה ולעמוד בראש בית דינם. יצירתו החשובה ביותר היא \"פסקי הרא\"ש\".</p>\n      <p class=\"book-p\">בנו של הרא\"ש הוא רבי יעקב בן-אשר, מכונה \"בעל הטורים\" על שם חיבורו הגדול \"ארבעה טורים\". רבי יוסף קארו השקיע שנים רבות ויקרות מחייו בעבודה על חיבור זה.</p>\n      <p class=\"book-p\" style=\"font-size:.8rem;color:rgba(237,224,196,.5)\">מקורות: ויקיפדיה, אתר דעת</p>\n\n      <h4 class=\"book-sub\">פגישת המזל בין הוריי</h4>\n      <p class=\"book-p\">אסילה שבמרוקו הספרדית, שוכנת לא רחוק מטנג׳יר, ויהודיה הכירו אלה את אלה. גם משפחת אבי הכירה את משפחת אמי, אך לא היו קשרים של ממש בין שתי המשפחות. הזמן חלף, אמי כבר הגיעה לפרקה, באותה התקופה ובאותו האזור היה גיל שש-עשרה ראוי לנישואין לכל הדעות, ועד מהרה נמצא לה חתן מיועד והשניים התארסו. זמן מה לאחר שהאירוסין כבר היו לעובדה מוגמרת, ובבית אמי החלו להכין את הנדוניה ולהתכונן לחתונה, הגיע אבי לטנג׳יר. באחד הימים, בעת מפגש חברתי או משפחתי, ראה את אמי והתאהב בה.</p>\n      <p class=\"book-p\">הוא ניגש אל סבתא סימי, שהייתה אז אם לחמש בנות ונשאה ברחמה הריון שישי, ואמר לה: \"גברת קארו, אני מבטיח לך שבפעם זאת בן ייוולד לך\". \"מאין אתה יודע זאת?\" התפלאה סבתי, ואבי רק אמר לה: \"אם יתברר שצדקתי - התתני לי את רינה בתך לאישה?\". סבתא הזדעזעה קלות ומחתה: \"אבל רינה כבר מאורסת!\" ואבי רק הוסיף ואמר: \"ובכל זאת...\"</p>\n      <p class=\"book-p\">סבתא כבר כרעה ללדת, ונבואתו של אבי התגשמה. בן נולד לה, דודי איזקה. שמחתה של סבתא סימי לא ידעה גבול ועד מהרה בוטלו האירוסין הקודמים. אמי רינה התארסה עם אבי שמואל, נושא הבשורה המשמחת, ונדמה לי כי אהבה גדולה מזו שהייתה ביניהם - לא יכול היה איש למצוא. אימא קראה לאבא \"מואואנו\" - אהובי, והוא קרא לה בחיבה - \"מיריינה\" (mi reina) - מלכה שלי.</p>\n\n      <h4 class=\"book-sub\">חיים בטנג׳יר</h4>\n      <p class=\"book-p\">תושבי טנג׳יר מצאו את פרנסתם במסחר, תיירות ודייג. גם אבי מצא את פרנסתו בים. אבא לא הגביל עצמו למלאכה אחת בלבד ועשה ככל יכולתו על מנת להביא פרנסה טובה הביתה. הוא סחר בחיטה ושעורה, עבד כצבעי, עסק בעבודות-עור, וצלל אל מעמקי הים במסגרת חברה אמריקנית ששלתה אוצרות שאבדו במעמקים. את ביתם קבעו אימא ואבא בטנג׳יר, במבנה מסורתי שבמרכזו חצר, אותו שכרו מבעל בית ערבי. בבית זה נולדו ששת אחיי הגדולים: יעקב (1901), יהודה (1903), משה (1905), מסוד (בעברית יהורם, 1907, נפטר במרוקו בגיל 32 בלבד) ואתי (1911). כולם נולדו בבית בעזרת מיילדת יהודייה בעלת ניסיון רב, כפי שהיה נהוג אז.</p>\n      <p class=\"book-p\">מובן שאיני זוכר דבר מאותה תקופה. טרם נולדתי... אולם ישנם סיפורים שעברו עם השנים במשפחה ואלה נמצאים בקיפולי נפשי ממש כמו זיכרונות אמיתיים. לעתים אני נוטה להתבלבל אם זה משהו שסיפרו לי או משהו שחוויתי. כך או כך, בהיות אחי יהודה פעוט, היה חולני ולא חש בטוב לאורך תקופת מה. אמי שנכבשה בייסורים עזים על חולניותו של יהודה הקטן, התייעצה בשכנותיה ואלה יעצו לה פתרון מוכח ומוצק: ביקור בבית הקברות יעזור לפטור את העולל מהמחלות.</p>\n      <p class=\"book-p\">אימא עשתה כעצת הנשים, ניגשה אל בית הקברות, הניחה את יהודה על הקבר והגתה את שאמרו לה לומר. באותו הרגע, כך סיפרה לי אימא לימים, יצא נחש ירוק מבין הקברים, סבב סביב התינוק אך לא חנק אותו. יהודה שעד זה לא מכבר היה חלוש מכדי להוציא הגה מפיו, נתן קולו בבכי רם. הדבר נראה בעיני אמא כנס והיא בכתה יחד אתו מאושר והקלה.</p>\n\n      <h4 class=\"book-sub\">העיר הלבנה</h4>\n      <p class=\"book-p\">אחיי הגדולים גדלו ובגרו. יום אחד קיבל אבא מכתב מהשלטונות הספרדיים ששלטו באזור כולו, המבשר כי עם הגיעם לפרקם יגויסו בניו אל הצבא. מבחינת אבא הייתה זו גזירה שאין כל דרך לעמוד בה, ותוך זמן קצר הוא בישר לאימא כי הם עומדים לעזוב את טנג׳יר ולעבוד לקזבלנקה שבמרוקו, שם לא ישיגום ידי השלטון הספרדי.</p>\n      <p class=\"book-p\">זמן קצר אחר-כך, נפרדו הוריי מבני המשפחה, ארזו את חפציהם, נטלו את ששת ילדיהם ועברו לקזבלנקה. משקבעו אימא ואבא את ביתם בקזבלנקה הגיע אליהם מכתב נוסף המתריע על גיוס, הפעם מאת השלטון הצרפתי. אלא שבמרוקו הצרפתית, בשונה מהמצב במרוקו הספרדית, על-אף שהשלטון מגייס נהגו המרוקאים להישאר בביתם לא חשש, ועולם כמנהגו נוהג. באותו יום החליט אבא שמעתה ואילך איננו ספרדים עוד, כי אם מרוקאים, וקזבלנקה היא ביתנו וכך היה. המשפחה נותרה בקזבלנקה.</p>\n      <p class=\"book-p\">בקזבלנקה הביאו הוריי לעולם חמישה ילדים נוספים. רחל נולדה ראשונה (1920, ונפטרה בגיל צעיר, רק בת 18), ושנתיים מאוחר יותר נולד אהרון (1922). בשנת 1923 נולדה אסטריה, אך נפטרה בדמי ימיה, כתינוקת רכה. אחד מאחיי התגעגע אליה געגועים עזים. הוא שב ואמר שהוא \"רוצה אסטריה\" פעמים לאין מספר, ובשנת 1925, כרעה אמי ללדת פעם נוספת. לבת שנולדה קראו אסטריה, כשמה של התינוקת שמתה. ב-20 בדצמבר, שנת 1927, נולדתי אני, פנחס, בן הזקונים של הוריי.</p>\n\n      <h4 class=\"book-sub\">אחותי פאני</h4>\n      <p class=\"book-p\">עשרה ילדים גידלו וחינכו הוריי, ולא אמרו די. יום אחד הייתה אמי בבית עם העוזרת, ולפתע ראתה מבעד לחלון איש חולף ליד ביתנו, ולצדו צועדת אישה שמחזיקה תינוקת צעירה בידיה. אימא נרעדה. גם העוזרת הבחינה בהם ואמרה לאמא: \"סניורה ריינה, הם הולכים לעבר בית-השעשועים שבסוף הרחוב, הם ודאי מתכוונים למסור שם את התינוקת\". אמי התרגשה ואף מחתה מעינה דמעה.</p>\n      <p class=\"book-p\">אחר ביקשה מהעוזרת לרוץ אחריהם ולקרוא להם להיכנס לביתנו. עד מהרה שבה העוזרת עם בני הזוג והפעוטה. אמא פתחה במסכת שכנועים, אלא שהגבר והאישה שעמדו שם לא היו זקוקים לשכנועים רבים. האישה הצעירה הסתבכה בהיריון מחוץ לנישואים. הייתה זו בושה גדולה בשבילה וכדי לשוב ולחיות בקהילתה היה עליה לוותר על בתה ולעזוב את העיר. אותה אישה הסכימה מיד להשאיר את התינוקת אצל אמי. אימא שלא ידעה קרוא וכתוב, הבינה בפיקחותה שיש לתעד את האירוע כראוי. אחי דוד כתב עבורה מכתב שעליו חתמו האיש והאישה, ובו צוין שהם מוותרים על הילדה והיא נמסרת לאמא מרצונם החופשי. מאז לא ראינו אותם עוד.</p>\n      <p class=\"book-p\">לאחר מכן שלחה אימא את אחותי אסטריה, אל אבא שישב באותה עת בבית-קפה, וביקשה שתגיד לו ש\"אימא לקחה ילדה\". כעבור זמן קצר שבה אסטריה הביתה ובפיה מילים שאבא מסר לה: \"מזל טוב\". בזאת נחתם באופן רשמי האימוץ של הקטנה בבית הוריי.</p>\n      <p class=\"book-p\">פאני, התינוקת שננטשה על ידי אימה הצעירה, גדלה אתנו כאחות לכל דבר. לימים, משנודע לנו דבר אימוצה השביעה אותנו אימא שלא נספר לפאני דבר על-כך, ואנו נשבענו וקיימנו את שבועתנו. רק שנים רבות מאוחר יותר פגשה פאני את בת-דודתי, וזו סיפרה לה על האימוץ. פאני ההמומה נלכדה בסערת רגשות שטלטלה את עולמה. חוסר-אונים ורחמים עצמיים סערו בקרבה, אך בסופו של דבר היא נרגעה והודיעה כי החדשות ששמעה אינן משנות דבר מבחינתה. הוריי הם הוריה, אני, אחיותיי ואחיי הם אחיה, ואת זיכרונות הילדות הטובה שהייתה מנת חלקה, שום דבר לא יוכל לגזול ממנה.</p>\n      <p class=\"book-p\">פאני היא אחותי לכל דבר ודבר, ואנו תמיד היינו המשפחה היחידה שאותה הכירה ואהבה.</p>\n\n      <h4 class=\"book-sub\">שגרת חיים בקזבלנקה של ילדותי</h4>\n      <p class=\"book-p\">בקזבלנקה התגוררנו בבית גדול בן שתי קומות וחמישה חדרים, ברחוב \"הצלב האדום\", רו-דה-לה-קרואה (Rue de la Croix). בקומה הראשונה היו המטבח, השירותים ושני חדרים, ובקומה העליונה היה חדר שירותים נוסף ועוד שלושה חדרי-שינה. אני עדיין יכול לראות את הבית הזה לנגד עיני, אך במיוחד צרוב בזיכרוני מראה הדלת שלו, כמותה לא ראיתי בישראל מעולם. הייתה זו דלת שכדי לפתוח אותה היו מושכים אותה מלמעלה.</p>\n      <p class=\"book-p\">ביתנו היה מחובר לחשמל, וגם מים זורמים היו בו, אך לא תמיד. המים נאגרו על הגגות, משם זרמו אל הצינורות ומהם לברזים. במים האלה התרחצו, כיבסו בגדים ושטפו רצפה, אך לשתייה - לא היו ראויים. את מי השתייה קנו מן הערבי שהיה עובר ברחובות העיר כשהוא נושא עמו נאד גדול של מים.</p>\n      <p class=\"book-p\">מלאכת הכביסה הופקדה בידיה של עוזרת-בית ערבייה, לאחר השפשוף המפרך הייתה תולה את הכביסה על הגג, כפי שהיה נהוג בקזבלנקה. המשרתת הערבייה התגוררה אתנו בבית ואף סעדה על שולחננו. כשאימא הייתה מבשלת - היא הייתה עוזרת לה גם במלאכות המטבח - מקלפת ירקות, שוטפת כלים ועוד, בעוד אימא הייתה יושבת על השרפרף שליד התנור הקטן שעמד במרכז המטבח, משגיחה על הסירים ומלבה את האש במפוח. עבור אימא, שגידלה עשרה ילדים, זו הייתה עזרה שלא תסולא בפז.</p>\n      <p class=\"book-p\">עובד נוסף היה מגיע לביתנו, הוא היה יהודי ונהגנו בו כבן בית, אך לא גר עמנו. מרבית תפקידיו היו בתחום התיקונים והאחזקה בבית, וכל מיני מלאכות שהוריי נזקקו להם. לקראת חג הסוכות היה בונה את הסוכה שלנו, תוך הקפדה על הלכות הסוכה ושמירה על כשרותה.</p>\n      <p class=\"book-p\">נולדתי לבית מלא אחים ואחיות, שופע קולות, מהומה ושאון--ילדים. יום אחד, בעודי תינוק, מתחו אחיי, דוד ומסעוד, חבל בין שני קצוות הבית, עליו כרכו מעין סל עשוי בד, ואותי, הפעוט, הניחו בתוך ערימת הסמרטוטים. אחר הם משכו אותי מעל החבל מצד לצד, ככדור-עף אנושי. כנראה אחיי חשבו שאני מעין צעצוע...</p>\n      <p class=\"book-p\">אבא המשיך תמיד לעסוק בכל העבודות ששימשו לו מקור פרנסה, ודבר לא חסר בבית. הייתי קטן מכדי לחשוב שמשהו מכל זה עומד להשתנות, ובעוד זמן לא רב. לעת עתה הייתה לי ילדות מאושרת בבית גדול, שמח ומלא בבני משפחה אוהבים.</p>\n    </div>\n    \n    <div class=\"book-chapter\" id=\"book-ch2\">\n      <h3 class=\"book-ch-title\">פרק ב': מעגל השנה</h3>\n      <p class=\"book-ch-page\">עמודים 19-24</p>\n      <h4 class=\"book-sub\">טעמה של שבת</h4>\n      <p class=\"book-p\">את ימות השנה ציינו אז, כהיום, מועדים וימי-אבל. בביתי נחגגו החגים ככתבם וכלשונם, על תפילותיהם, הכנותיהם ושלל ריחותיהם. יהודי מרוקו היו כולם אנשים דתיים ושומרי-מסורת, משום כך אותם מאפיינים שראיתי והרגשתי בביתי, היו נהוגים בבתי היהודים בשכונה כולה. עד היום, ביום שישי, לעת שקיעת החמה, כשאווירה מיוחדת יורדת על ירושלים, אני נזכר בשבת של קזבלנקה. השבת של ילדותי.</p>\n      <p class=\"book-p\">בשבת היה אבא אתנו בבית, ואימא הייתה חדלה ממלאכות הבית שאין להן התחלה ואין להן סוף. כולנו לבשנו את מיטב בגדינו הנאים, וחילקנו את זמננו בין התפילות, הארוחות, המשחקים והמנוחה.</p>\n      <p class=\"book-p\">אחד מסימני ההיכר של השבת היה ריח החמין, שנישא כשובל שמלתה של שבת המלכה, מן המאפייה אל הבית. את החמין הייתה אימא מכינה, ככל שכנותיה, בכלי חומר עמוק שנקרא טאג׳ין. על שוליו הייתה מדביקה רצועות בצק ואלה הקנו לו אפקט של סיר-לחץ ושמרו על חום התבשיל שבתוכו. מכיוון שכל היהודים הטמינו את סירי החמין שלהם בתנור המאפייה, היו לעתים נופלות טעויות, ולא אחת קרה כי חמין של משפחה אחרת הגיע אל שולחננו. ובכל זאת תמיד היה לו את אותו טעם מיוחד, טעם של שבת.</p>\n      <h4 class=\"book-sub\">חגי תשרי</h4>\n      <p class=\"book-p\">ראש-השנה הוא חג שאולי יותר מכל מבשר התחלה חדשה, נקייה. חלק גדול מהיום הקדוש היו אבי ואחיי מעבירים בבית הכנסת. כשאני חושב על ראש-השנה בבית הוריי, התמונה הראשונה שעולה בדעתי, היא סיר הקוסקוס הגדול שאליו התלווה מרק ירקות עשיר וטעים שאימא הכינה לכבוד החג.</p>\n      <p class=\"book-p\">לא חלף שבוע, וכבר התקדש ובא יום-הכיפורים. מספר ימים לפני ערב יום-הכיפורים היו הוריי קונים תרנגולים ותרנגולות לטקס הכפרות. יום לפני רדת החג, היו הוריי מזמינים שוחט הביתה. לאחר מכן נקראנו כולנו להשתתף במלאכת ניקוי התרנגולות השחוטות וניקוי החצר שהזדהמה בדמן.</p>\n      <p class=\"book-p\">אנו התפללנו בבית-הכנסת הקרוב לביתנו, שנקרא על שם אטדגי, היהודי הספרדי שבנה אותו, ובתקרתו נתלו נברשות ענקיות עשויות כוסות מבריקות עצומות ממדים.</p>\n      <p class=\"book-p\">לאחר שהלך אבא לעולמו, משקרב ובא יום הכיפורים, בכתה אימא כי אין לנו כסף לקנות בו עופות לכפרות. יום אחד שמענו רעש מכיוון הגג. לתדהמתנו הרבה, כמו לפי הזמנה, מצאנו על גג הבית ארבעה עופות שרגליהם קשורות. מבחינתנו לא היה זה אלא נס.</p>\n      <p class=\"book-p\">עם צאת יום הכיפורים היינו מתגייסים למצוות בניית סוכה. הסוכה נבנתה על גג הבית, ובימי החג יכולנו לראות סוכות רבות שכמו צמחו בין לילה על גגות הבתים, מסמלות כמזוזה ענקית את מקומות מגוריהם של היהודים.</p>\n      <h4 class=\"book-sub\">ימי משתה ושמחה</h4>\n      <p class=\"book-p\">את חג החנוכה סימלו הנרות שהיינו מדליקים פתילות של שמן שהונחו בחנוכיות, וכמובן - הספינג׳, הסופגניות המרוקאיות הנהדרות שהייתה אימא מכינה. את חג הפורים סימנה קריאת המגילה בבית-הכנסת ברוב עם ורעש, ומנהג משחקי הקלפים שהיינו משחקים מאוחר יותר בבית.</p>\n      <h4 class=\"book-sub\">שיגעון הפסח</h4>\n      <p class=\"book-p\">את ההכנות לפסח, שהתחילו כמעט מיד לאחר שנגמר חג-הפורים, סימן עבורי צמצום תחום המחייה שלי בבית. אימא לא הייתה מרשה לנו להיכנס בלי ניעור כהלכה לנגד עיניה, שתראה כי כל החמץ נושר ולא עובר את סף הבית. מיום ליום הורחקנו יותר ויותר משטח המטבח עד כי ביום שלפני החג מצאנו עצמנו ממש על מפתן הבית...</p>\n      <p class=\"book-p\">עם התקדש החג הייתה האווירה כולה משתנה. הבית היה נקי ומצוחצח, אימא נראתה נינוחה, והשולחן הארוך שעליו נערכו כלי הפסח החגיגיים הגביר בנו את הציפייה. אבא היה קורא בקול רם וצלול בעברית, והיה שב וחוזר על כל הקטעים גם בלדינו ובמרוקאית. כך נמשכה קריאת ההגדה זמן ארוך פי שלוש.</p>\n      <h4 class=\"book-sub\">\"תרווחו ותסעדו!\" — המימונה</h4>\n      <p class=\"book-p\">ללא ספק היום הנחמד ביותר, היה זה שבסופו של חג הפסח, יום המימונה. בכל בית היו הנשים עמלות ומכינות מופלטות, ולצידן ריבות ומטעמים מתוקים לאינספור. שולחן ארוך היה נפתח בבתי היהודים, ועליו נערמו צלחות עמוסות של מיני מתיקה - מופלטות, דבש, חלב, ריבות, פירות יבשים לרוב, מרציפנים עשויים שקדים. וגולת הכותרת: \"פגז\" של סוכר מוצק שנצבע בצבעים בוהקים.</p>\n      <p class=\"book-p\">ליל המימונה היה \"לילה לבן\". משפחות היו מבקרות אלו אצל אלו, כולם לבושים בגדי חג מסורתיים, נכנסים בשירה ומברכים: \"תרווחו ותסעדו\". באותו לילה לא רק יהודים היו מבקרים בבתינו, אלא גם שכנינו המוסלמיים. היה זה לילה של קירוב לבבות ואחווה בין איש לרעהו ללא הבדל דת וגזע.</p>\n      <p class=\"book-p\">למחרת בבוקר היה השלטון הצרפתי מעמיד לרשות היהודים אוטובוסים, ואיתם היינו נוסעים לטייל בטבע, לרוב על שפת הים, שם היינו עורכים פיקניקים, צולים בשר על האש, מנגנים בדרבוקות, שרים שירים מרוקאיים ושמחים עד אין-קץ.</p>\n      <h4 class=\"book-sub\">חג בלבן — שבועות</h4>\n      <p class=\"book-p\">את חג השבועות ציינו שני מאפיינים עיקריים. האחד היה ה\"מלדדו\" - ליל שימורים, בו לומדים הגברים תורה כל הלילה בבית-הכנסת. כילד קטן, חיכיתי גם אני ליום שיותר לי ללמוד עם אבא. המאפיין השני היה שלל הגבינות. עדה דודתי הייתה חובצת גבינות בעצמה, ולקראת החג הייתה מגיעה לביתנו ומרעיפה עלינו ממעשי ידיה.</p>\n      <h4 class=\"book-sub\">קינות תשעה באב</h4>\n      <p class=\"book-p\">את מועדי השנה המרכזיים חתם יום המספד והאבל של תשעה באב. אימא הייתה בוכה ומתייפחת שעות רבות. היום בו מזכיר העם היהודי את אסונותיו ובראשם חורבן בית-המקדש, היה עבורה תזכורת לכל חורבן ואסון שהתרחש במשפחה. אני זוכר את עצמי כילד קטן ניגש אל אימא ומנסה להרגיעה, ואימא מנסה להשתלט לרגע על רגשותיה, וזמן קצר לאחר מכן שבה ומתייפחת.</p>\n    </div>\n    \n    <div class=\"book-chapter\" id=\"book-ch3\">\n      <h3 class=\"book-ch-title\">פרק ג': מרוקו של ילדותי</h3>\n      <p class=\"book-ch-page\">עמודים 25-34</p>\n      <h4 class=\"book-sub\">ילדות</h4>\n      <p class=\"book-p\">זיכרונות חיי הראשונים רוויים בצבעים, בקולות ובריחות של \"רו דה לה קרואה\" - רחוב \"הצלב האדום\", בו נולדתי וגדלתי. עת שעשיתי את צעדיי הראשונים בעולם, כבר היו ארבעה מאחיי - יעקב, משה, יהודה ואתי - נשואים, והתגוררו בבתים משלהם. בבית הגדול והיפה שאימא ואבא שכרו מערבי עשיר, נותרו אז חמישה ילדים. עולמי היה בוטח ושלו, וכילד סקרן ומשולח כל רסן, חקרתי את סביבתי.</p>\n      <p class=\"book-p\">אהבתי להתלוות אל אימא כשהלכה לשוק היהודי. הצבעוניות והריחות שעלו מכל עבר הפעימו אותי. הכול יכולנו למצוא שם - פירות, ירקות, חמוצים, תבלינים, מזון יבש. כשאמא קנתה מהקצב היהודי בשר, הוא בצע אותו בדיוק במקום עליו הצביעה אימא. את החלב היה מביא הרוכל עד פתח ביתנו. מדי יום עבר ברחוב רוכל עם שתי עזים שעל צוואריהן נקשרו פעמונים שבישרו את בואן. כשנשמע צלצול הפעמונים הייתה אימא יוצאת החוצה וכלי קיבול בידה, והרוכל היה ממלא את הכלי היישר מעטיניה של העז. דבר לא חסר לנו.</p>\n      <h4 class=\"book-sub\">חיים אחרים</h4>\n      <p class=\"book-p\">אימא, שעול גידול הילדים וטיפוח הבית היה כבד עליה, שלחה אותי, בעצת שכנותיה, לגן ברחוב הכנסייה הספרדית. באותו גן נוצרי ראיתי לראשונה בחיי חיים אחרים לחלוטין מכל מה שהכרתי. הנזירות שניהלו אותו לימדו אותנו שירים בספרדית, ומדי פעם היה הכומר מגיע לגן, עובר מילד לילד, וחלק מהילדים היו נושקים לצלב הענק שהיה תלוי על צווארו. אבל בתוך תוכי ידעתי שאין זה מקומי כיהודי.</p>\n      <h4 class=\"book-sub\">ימי בית הספר</h4>\n      <p class=\"book-p\">הוריי רשמו אותי לבית-ספר מרשת \"אליאנס\" (Alliance Israelite Universelle), ארגון תרבותי-יהודי שפעל במספר ארצות. מדי בוקר כשיצאתי אל בית-הספר לבשתי את התלבושת האחידה - מעין חלוק שחור עם צווארון לבן. שעה אחת בשבוע יוחדה ללימודי לשון הקודש בעברית, ופרט לשעה זו למדנו מקצועות חול בלבד: חשבון, קריאה, היסטוריה, גיאוגרפיה, אנגלית ועוד.</p>\n      <p class=\"book-p\">לא קל היה לי בבית-הספר. אני מודה שהתקשיתי בקריאה ובכתיבה. בין חבריי לכיתה היו ילדים למשפחות עשירות שנעזרו במורים פרטיים, ולי לא היה איש. אבא עבד מבוקר ועד ערב, אמא לא ידעה קרוא וכתוב, ואחיי הגדולים היו עסוקים. פעם ציווה עלינו המורה ללמוד בעל-פה קטע. עמדתי בפני המורה והכיתה ברגליים רועדות ושפתיים קפוצות, ואף מילה לא מצאה דרכה אל פי. המורה הכין את השוט ו\"זיכה\" אותי בארבעים מלקות על כפות ידיי. שבתי למקומי חבול ודומע.</p>\n      <p class=\"book-p\">יום אחד פנה אליי חבר, שסבלי נגע ללבו: \"פנחס, לפני שאתה מגיע לשיעור קח כמה שיני שום, כתוש אותן ושפשפן היטב בכפות ידיך. אם תעשה זאת - לא יכאיבו לך מכותיו של המורה\". וכך אכן עשיתי. באותו יום באמת לא הכאיבו לי הצלפותיו של המורה שהתמלא תדהמה למראה שלוות הנפש שבה קיבלתי את מכותיו, ומאז הניח לי.</p>\n      <p class=\"book-p\">רק אדם אחד לא היה מוכן להשלים עם הגזרה: אמי היקרה. אימא ראתה את סבלי ואת ידיי החבולות, ולבה כאב. חברותיה הציעו לה סגולה בדוקה: \"ביום שישי, לאחר שתלושי את הבצק מהקערה ותקלעי ממנו חלות לכבוד שבת, מלאי את הקערה במים, ואת המים הלבנים שיישארו - צקי לכוס נקייה ותני לפנחס לשתות.\" אימא עשתה כן, ולהפתעת כולם - מאותו יום ואילך התחלתי להצליח בלימודים.</p>\n      <h4 class=\"book-sub\">קסם המסך הגדול</h4>\n      <p class=\"book-p\">מגיל צעיר אהבתי ללכת לצפות בסרטים בקולנוע. בכניסה לקולנוע עמד חבר של אחי שחיבב אותי והניח לי להיכנס ללא תשלום: טרזן, מיקי-מאוס, ועוד סרטים אמריקאים. יום אחד, במקום ללכת לבית הספר, שמתי פניי אל הקולנוע. זה היה יום נפלא! אך המורה שהבחין בהיעדרותי שלח פתק לאימא, ואבא, שבתוך שניות הבין שילד החמד שלו גם משקר, \"זיכה\" אותי בשלושים ושש הצלפות משוט יבש, כשהוא מונה אותן עם הפסוק: \"והוא רחום יכפר עוון...\"</p>\n      <h4 class=\"book-sub\">בארץ זרה</h4>\n      <p class=\"book-p\">\"סג׳יף\". יהודי מלוכלך. כך כינו אותנו הנוצרים של קזבלנקה, ובעקבותיהם גם המוסלמים. כילדים הרגשנו פחד, יכולנו להריח את השנאה ברחובות. היא הייתה מתפרצת במיוחד בימי שישי לאחר התפילה ונאומי האימאמים במסגדים. אמי המסכנה הוכתה פעם בברזל שאחז מוסלמי עיוור, רק מפני שהבין שהיא אינה מוסלמית. אותו יום אימא שבה הביתה בוכה.</p>\n      <p class=\"book-p\">איש לא דיבר אז על עלייה לארץ-ישראל, ואת כל מה שידענו עליה שאבנו מן העיתונות הצרפתית. בעיתונים נקראה הארץ \"פלשתינה\". רק בבית הכנסת אפשר היה לדבר בחופשיות.</p>\n      <h4 class=\"book-sub\">תום הילדות</h4>\n      <p class=\"book-p\">אבא לא יכול היה להימנע מעישון, ובגיל צעיר יחסית חלה במחלת ריאות קשה. בימיו האחרונים אבא כמעט לא ירד מהמיטה ואימא טיפלה בו. באותם ימים בהם אבא שכב חולה, הייתי חופשי לעשות כרצוני, ומה שמשך אותי הייתה חנות התיקים של שכנינו. המשכורת הראשונה שקיבלתי מנתה פרוטות ספורות. הלכתי למכולת וקניתי בהן נרות וגפרורים. כששבתי הביתה הושטתי אותם לאמי מבלי לומר מילה, ובעיניה עלו דמעות.</p>\n      <p class=\"book-p\">בשלהי שנת 1939, עמדתי לצדה של אמי במטבח, בעת שלשה בצק לחלות השבת. לפתע הרעיד רעם פיצוץ אדיר את ביתנו. אנייה צרפתית מלאה בחומר נפץ התפוצצה בנמל קזבלנקה. אבא אמנם לא נהרג במקום, אך הפיצוץ שהעיף אותו ממיטתו עד לתקרה ובחזרה גרם לו לנזק פנימי בלתי הפיך. תוך זמן קצר התחיל אבא להקיא דם, וכעבור שלושה או ארבעה ימים - בכ\"ו בחשוון, נובמבר 1939 - השיב את נשמתו לבורא.</p>\n      <p class=\"book-p\">בעל כורחי התבגרתי באחת. הייתי אז רק בן אחת-עשרה, וכדי שאוכל לומר \"קדיש\" על הקבר הוכרזתי כבר-מצווה. את הטלית שבנסיבות הרגילות היו עוטפים אותי בה בעת העלייה לתורה, עטיתי לראשונה מעל הקבר הטרי, ובקול חנוק, מתוך מבט מעורפל מדמעות, הצטרפתי לקדיש.</p>\n      <p class=\"book-p\">זמן קצר לאחר מכן, בטרם סיימתי את כיתה ח', עזבתי את הלימודים.</p>\n    </div>\n    \n    <div class=\"book-chapter\" id=\"book-ch4\">\n      <h3 class=\"book-ch-title\">פרק ד': כמיהה ציונית</h3>\n      <p class=\"book-ch-page\">עמודים 35-42</p>\n      <h4 class=\"book-sub\">לאחר מותו של אבא</h4>\n      <p class=\"book-p\">טקס בר-המצווה שנערך לי מעל קברו של אבא חתם את ילדותי. אימא הרעיפה עליי אהבה ותשומת-לב רבה, אך היא לא ידעה קרוא וכתוב ולא יכלה לעקוב אחר לימודיי, ואבא - שבזמן שהיה בחיים פקח עליי עין - לא היה עוד.</p>\n      <p class=\"book-p\">אבא היה איש רזה אך חזק. קשוח וענייני, ששומר על דיסטאנס, רוב הזמן רציני. לצד זה היה איש חם ואוהב. זוכר אני את דמותו, לבוש בג׳לביה, וכשהיה לי קר - היה מכניס אותי תחת הג׳לביה שלו, מחבק אותי ומחמם אותי. מותו היה מכה קשה למשפחה והוריד עצב כבד על הבית.</p>\n      <h4 class=\"book-sub\">העבודה הראשונה שלי</h4>\n      <p class=\"book-p\">לאחר מותו של אבא עזבתי את בית הספר, עוד לפני שסיימתי את כיתה ח׳. המשכתי לעבוד כפועל במפעל התיקים והארנקים. בקזבלנקה תיקים היו פריט אופנה הכרחי. בעל-המפעל היה ערבי, ובין הפועלים היו ערבים ויהודים. התחלתי מעבודות ניקיון, אך עם הזמן למדתי לגזור ולתפור את התיקים, והכרתי את העורות השונים - עור של סוס, עור לביאה ועוד.</p>\n      <p class=\"book-p\">בגיל שלוש-עשרה וחצי כבר הייתי עצמאי קטן, מעין קבלן משנה. בעל-המפעל היה מספק לי את העורות, ובעזרת שני פועלים שהעסקתי הייתי מכין תיקי ילדות עבורו.</p>\n      <h4 class=\"book-sub\">הרחק מפה - מלחמת העולם השנייה</h4>\n      <p class=\"book-p\">מלחמת-העולם השנייה פרצה כשהייתי בן שתים עשרה. ידענו על התקדמות הצבאות, אך על המחנות לא ידענו דבר. על הזוועות שנעשו ביהודי אירופה שמענו לראשונה מפי הפליטים הבודדים שהצליחו לברוח מפולין ולהגיע בדרך לא דרך לקזבלנקה.</p>\n      <h4 class=\"book-sub\">בתנועת הנוער</h4>\n      <p class=\"book-p\">בגיל חמש-עשרה הצטרפתי לראשונה לתנועת-נוער ציונית - \"הפועל המזרחי\". במסגרת הפעולות היינו עורכים מסדרים, למדנו על הציונות, שמענו סיפורים על ארץ-ישראל ועל מחנות המעצר בקפריסין. בערבי שבת היינו הולכים לבית קרל-נטר, שם היינו מבלים עם בני-נוער מכל תנועות-הנוער הציוניות שהיו בקזבלנקה.</p>\n      <p class=\"book-p\">בנעוריי למדתי לנגן באקורדיון אצל פרופסור ברינגולה, איטלקי. ניגנתי יפה והתקדמתי היטב. הפרופסור לימד אותי גם קונטרבס ותופים. באותו יום בו עמדתי בקרן הרחוב ומכרתי את העיתון \"הקול היהודי\" (Le Juive), עבר לידי הפרופסור, קנה עיתון וחייך. כל-כך הייתי גאה למכור את \"הקול היהודי\" לאיש נוצרי.</p>\n      <h4 class=\"book-sub\">ביקור משפחתי בעיר אסילה</h4>\n      <p class=\"book-p\">לקראת חגי תשרי נסעתי לאסילה, עיר הולדתו של אבי. בגבול שבין תחום השלטון הצרפתי והספרדי הורידו אותי מהאוטובוס - לא היה לי ויזה. נסעתי לטנג׳יר לקרובת משפחה, ובעלה שעבד ברכבת עזר לי לעבור לאסילה.</p>\n      <p class=\"book-p\">באסילה ביקשתי לדבר בפני מתפללי בית-הכנסת. סיפרתי להם על הרעיון הציוני ועל תנועות הנוער, הראיתי להם סמל כחול-לבן. ביום ראשון יצאנו לשדה, לימדתי אותם לעדור ולהכין את האדמה לחקלאות, ללמוד \"הבה נגילה\" ולרקוד הורה. בת דודתי אלגריה (שמחה) שרה לי עד היום: \"אנו באנו ארצה לבנות ולהיבנות בה...\"</p>\n      <h4 class=\"book-sub\">לבי במזרח</h4>\n      <p class=\"book-p\">רעיונות הציונות והכמיהה לארץ-ישראל כבשו אותי כליל. הבנתי שאין ליהודים מקום בעולם, אלא בארץ-ישראל. הכמיהה לארץ פעמה בי ומחשבה אחת ליוותה אותי: אני רוצה לעלות לארץ-ישראל ולמות עם נשק ביד, אם צריך. כשאחיי שמעו על כך הם היו מופתעים עד מאוד. רעיון העלייה ארצה הכה שורשים בלבי וידעתי כי ימיי במרוקו ספורים.</p>\n    </div>\n    \n    <div class=\"book-chapter\" id=\"book-ch5\">\n      <h3 class=\"book-ch-title\">פרק ה': אל הדרור</h3>\n      <p class=\"book-ch-page\">עמודים 43-50</p>\n      <h4 class=\"book-sub\">בתנועת הנוער</h4>\n      <p class=\"book-p\">הייתי כבן חמש-עשרה וחצי כשהבנתי שעתידי אינו בקזבלנקה. יום אחד אמר לי חבר: \"הפועל המזרחי אינה התנועה הציונית היחידה. אם תצטרף לתנועת הדרור מיד ישלחו אותך לארץ ישראל\". מבלי להסס עזבתי את \"הפועל-המזרחי\" ועברתי ל\"דרור\". כל שרציתי זה לעלות לארץ ישראל, ולא היה אכפת לי איך זה יקרה ועם מי.</p>\n      <h4 class=\"book-sub\">במחנה ההכשרה</h4>\n      <p class=\"book-p\">מחנה ההכשרה נערך בעיר קטנה על גבול מרוקו-אלג׳יר, ונמשך כשבועיים. לימדו אותנו קרב פנים אל פנים במקל, סכין ואקדח. עברנו גם אימוני נשק - למדנו לפרק נשק ולהרכיב אותו בחזרה, לנקות אותו, להכניס כדור, לכרוע ברך ולכוון אל המטרה. רק שלירות ממש לא ירינו.</p>\n      <h4 class=\"book-sub\">יוצא לדרך בלתי לגאלית</h4>\n      <p class=\"book-p\">חולקנו לחוליות של ארבעה חברים, וחולקו לנו דרכונים מזויפים. הדרך לגבול אלג׳יר עברה בחוף הים ואנו יצאנו לשם לבושים כנופשים. עם החשכה לבשנו את בגדינו. בארבע לפנות בוקר העיר אותנו המדריך ושלח שני בחורים לבדוק את אזור הגבול. אט אט נכנסנו אל התחנה ועלינו על האוטובוס הנוסע לכיוון אלג׳יר.</p>\n      <p class=\"book-p\">באוג׳דה ראינו נשים יהודיות בבגדי אבלות. המדריך סיפר על הפרעות שנערכו ביהודי המקום - ב-7 ביוני 1948 נרצחו עשרות יהודים. הסיפור הקשה חיזק עוד יותר את רצוני להילחם על מדינתי כיהודי גאה.</p>\n      <h4 class=\"book-sub\">בהכשרה בצרפת</h4>\n      <p class=\"book-p\">ממרסיי הביאו אותנו לארמון ב\"שאטו מון ברדו\", שבו הוקמה חווה חקלאית להכשרה. גידלתי שפנים, עבדתי בכרמי ענבים. יום אחד כאשר ביקשתי מים, האיכרים צחקו: \"אצלנו בכרמים לא שותים מים\" ומזגו לי יין אדום.</p>\n      <p class=\"book-p\">כשלושה חודשים לאחר שהגענו התחלנו לשמוע ברדיו על קרבות מלחמת העצמאות ועל הנופלים הרבים. החלטנו כי די לנו בחיים הפסטוראליים בצרפת, ואף פצחנו בשביתת רעב.</p>\n      <h4 class=\"book-sub\">על הספינה</h4>\n      <p class=\"book-p\">ביולי 1948 עלינו על האנייה \"סנט אנטוניו\" שהייתה במקור ספינת דייגים. על האנייה היו כארבע-מאות איש. ישנו בבטן האנייה, שמונה אנשים בתא, במקום בו נהגו לאחסן דגים. כבני-נוער היינו מלאי חזון ושמחה, ומדי פעם פרצנו בשירה נלהבת ובריקודי הורה על הסיפון.</p>\n      <p class=\"book-p\">לבסוף, בשעת לילה מאוחרת, ראינו מן הסיפון את אורותיה של חיפה. לרגע נעתקה נשימתנו מרוב התרגשות. לאחר מכן פרצנו כולנו בשירת התקווה. כשהגענו לחיפה, ירדנו אל החוף, כרענו אפיים ארצה ונישקנו את אדמת הארץ.</p>\n    </div>\n    \n    \n    <div class=\"book-chapter\" id=\"book-ch6\">\n      <h3 class=\"book-ch-title\">פרק ו': ימים ראשונים בארץ</h3>\n      <p class=\"book-ch-page\">עמודים 51-56</p>\n      <h4 class=\"book-sub\">\"אין נעליים — אין אימונים!\"</h4>\n      <p class=\"book-p\">הנחתי את רגליי על אדמת ארץ ישראל לראשונה ב-11 בנובמבר 1948, והייתי מאושר. זמן רב כל-כך הקדשתי את כל כולי לציונות ולטיפוח חלום העלייה. דקות ספורות אחרי שנפלנו אפיים ארצה ונישקנו את האדמה, פרצנו בהורה סוערת. אחר-כך נכנסנו אל משרדי הסוכנות ו\"התכבדנו\" במנה של תרסיס די-די-טי, מכף רגל ועד ראש.</p>\n      <p class=\"book-p\">לאחר מכן נערכו רשימות. איש לא שאל אותנו דבר, איש גם לא הסביר, ורק כשעמדנו מול הפקיד הבנו לקראת מה אנו הולכים. מי שהיה נשוי נשלח למגורים באחת המעברות, ומי שהיה רווק — מיד אל הצבא! וכך, דקות לאחר שירדתי מהאנייה, הועליתי על האוטובוס מחיפה לבית-ליד.</p>\n      <p class=\"book-p\">את מעט העברית שכבר הייתה בפינו ניצלנו לקיום השביתה הראשונה שלנו בארץ ישראל. עמדנו כולנו ושרנו אל מול פני המפקד: \"אין נעליים — אין אימונים!\". המפקד הסמיק עד לשורשי שערותיו.</p>\n      <p class=\"book-p\">עד מהרה מצאנו את עצמנו בשדה האימונים. למדנו להכניס כדור לרובים אנגליים וצ׳כיים, ירינו לעבר מטרה, זחלנו כמה מטרים, ואחרי יום-יומיים של אימונים — התבשרנו כי אנחנו מוכנים לקרב.</p>\n      <p class=\"book-p\">חילקו לנו מדים ישנים ומטולאים של הצבא הבריטי, ונעליים אזרחיות רגילות. המפקד שלנו הגיע עם נעליים צבאיות אדומות גבוהות ומבריקות. האפליה הזו כלפי העולים החדשים הייתה בלתי נסבלת.</p>\n      <p class=\"book-p\">לבסוף העלו אותנו על אוטובוס מכוסה ברשת הסוואה, לקראת היציאה אל הקרבות. רגע לפני שיצא האוטובוס, עלה מישהו וקרא מספר שמות. שמעתי את שמי וירדתי. \"פנחס בן הרוש?\" שאל הפקיד. \"יש לי כאן מכתב מטעם תנועת הדרור, אתה יוצא להכשרה בקיבוץ רגבים.\" באותו הרגע הסתיים שירותי הצבאי הראשון.</p>\n      <h4 class=\"book-sub\">שווים ושווים יותר — בבית אורן</h4>\n      <p class=\"book-p\">הוסענו לקיבוץ רגבים בנגב. היינו שם פרק זמן קצר ביותר, והעבירו אותנו לבית אורן. שובצתי לעבודה כרועה פרות. מדי בוקר הייתי יוצא אתן למרעה, נושם את אוויר הכרמל הצלול, ומתבונן בערגה על האדמה החקלאית. אהבתי מאוד את העבודה והרגשתי שנועדתי לחיי חקלאות וכפר.</p>\n      <p class=\"book-p\">שנה חלפה. יום אחד הרגשתי כאב בידי. הרופא שלח אותי לניתוח בחיפה. הורדמתי, טופלתי, התעוררתי, ונשלחתי חזרה לקיבוץ. כמה שעות אחר-כך, עדיין מטושטש, הלכתי לחדר האוכל וגיליתי שאני משובץ מיידית לעבודה ברפת.</p>\n      <p class=\"book-p\">\"בלתי אפשרי,\" ענה לי סדרן העבודה. \"אתה חייב לעבוד על פי השיבוץ.\" הסברתי שעברתי ניתוח, אך ללא הועיל. \"אם לא תחזור לעבודה מיד — אין לך מקום אצלנו בקיבוץ!\" הרגשתי כאילו כיוון לעברי רובה וסחט את ההדק.</p>\n      <p class=\"book-p\">חבריי תמכו בי והודיעו כי אם אאלץ לעזוב — יעזבו גם הם. המדריך אסף אותנו לשיחה ואמר: \"אתם חייבים להבין שאין מקום לעצלנים בקיבוץ שלנו.\" איבדתי את עשתונותיי. איש לא זכר את הלילות בהם קמתי לחלוב את הפרות, את ערמות החציר שנשאתי על כתפיי. הכול נמחק.</p>\n      <p class=\"book-p\">המדריך ניסה לרכך: \"הגעתם לכאן בחוסר כול. הקיבוץ נתן לכם אוכל וקורת גג. אם יש פה מישהו שאינו מרוצה — שירים את היד.\" מכל עבר התרוממו ידיים. כמה ימים מאוחר יותר הגיע יצחק טבנקין בכבודו ובעצמו, אך גם הוא דבק באותו הקו. בסופו של דבר עזבנו כולנו את הקיבוץ.</p>\n      <h4 class=\"book-sub\">בפרדס חנה</h4>\n      <p class=\"book-p\">עברנו למעברה בפרדס חנה. סטריה אחותי עלתה ארצה בינתיים והתגוררה שם. הימים במעברה הלכו וארכו והרגשתי שאני הולך ונחנק. את מרבית היום ביליתי בחוסר מעש ובעישון סיגריות לראשונה בחיי.</p>\n      <p class=\"book-p\">פעם ראינו חמור. עליתי עליו, הובלתי אותו לשוק ומכרתי אותו בלירה וחצי. בעליו אולי מחפש אחריו עד היום...</p>\n      <p class=\"book-p\">לבסוף הגיעה הבשורה: מושב ארבל, יישוב צעיר ליד כפר חיטים. \"בן הרוש, אנחנו נסיע אותך לשם, תבדוק אם זה מתאים, בעקבותיך יבואו שאר החברים.\"</p>\n      <h4 class=\"book-sub\">במושב ארבל</h4>\n      <p class=\"book-p\">התחלתי לעבוד ברפת ובדיר. בימים הראשונים היו עיניי נודדות אל שער המושב — חיכיתי לחבריי. הם לא הגיעו, אך אני התאקלמתי היטב במושב.</p>\n      <p class=\"book-p\">אהבתי לרעות את העדר. לכל פרה וכבשה היה שם. אסתי, הכבשה המנומרת שהובילה את העדר, הייתה הכבשה היפה ביותר וגם השובבה שבהן. מדי יום הייתי לוקח אתי את החליל ומוציא ארבע-מאות ראשי צאן למרעה. למדתי שכשאני רואה נחש עליי לקפוא על מקומי ולחכות שיעבור.</p>\n      <h4 class=\"book-sub\">האסון בארבל</h4>\n      <p class=\"book-p\">ב-20 ביולי 1950, לקראת ארוחת הצהריים, ראינו עשן כבד מיתמר מכיוון הצריף השוודי. חצי מהצריף שימש כבית התינוקות. רוח חזקה מכיוון טבריה הפכה פתיליה דלוקה והצריף החל לעלות באש. הגננת פתחה את הדלת כדי לקרוא לעזרה, אך הרוח שפרצה ליבתה את האש. כל התינוקות שהיו בצריף נשרפו חיים, ביניהם גם בתה של הגננת.</p>\n      <p class=\"book-p\">באותו היום הוקם בית הקברות של מושב ארבל. העוללים שקיפחו את חייהם היו הראשונים להיקבר בו. השריפה כילתה גם את תעודת הזהות ותעודת הלידה שלי, אך זה לא הטריד אותי. במשך ימים ארוכים לא יכולתי לחשוב אלא על הילדים הרכים שבקושי שנה מלאה להם.</p>\n      <p class=\"book-p\">אהבתי את החיים במושב ארבל וכשחשבתי על עתידי ראיתי עצמי חי שם ובונה את חיי. אך לא את החיים האלה הועיד לי גורלי. לא חלף זמן רב והכל השתנה מן הקצה אל הקצה.</p>\n    </div>\n    <div class=\"book-chapter\" id=\"book-ch7\">\n      <h3 class=\"book-ch-title\">פרק ז': סיפורה של פרלה</h3>\n      <p class=\"book-ch-page\">עמודים 57-66</p>\n      <h4 class=\"book-sub\">ילדותי הרחוקה</h4>\n      <p class=\"book-p\">קזבלנקה בשבילי היא מקום שמוהל את רגשותיי בין עצבות לצער, בין רגעי יגון לשביבי שמחה. כך או כך, היא המקום שבו החלו חיי.</p>\n      <p class=\"book-p\">אמי, סימי בוזגלו, נולדה בשנת 1908 בלרצ׳ה שבמרוקו הספרדית. לסבתי קראו רחמה. אמי גדלה בבית אמיד עם אחים ואחיות רבים: ג׳ולי, אורייט, אמיל, פיירו ואיבון. המשפחה עברה מלרצ׳ה לרבאט. בבית הספר בקזבלנקה הכירה אמי את אבי, יצחק איזק כהן. הוריי התחתנו כשהיו בני שבע-עשרה בלבד, צעירים, יפים ומאוהבים.</p>\n      <p class=\"book-p\">אבא עבד כספר ופתח מספרת גברים משלו שהצליחה יפה. נולדו שלוש בנות: ליליאן (1932), אני (1933), ואודט (1934). אך שלושה חודשים לאחר הולדתה של אודט חלתה אימא בדלקת ריאות קשה, נדבקה בשחפת, ובשנת 1936, בהיותה בת 26 בלבד, נפטרה.</p>\n      <h4 class=\"book-sub\">יתמות</h4>\n      <p class=\"book-p\">הייתי תינוקת בת פחות משנתיים. איני זוכרת דבר מאותם הימים. סבתא רחמה נטלה את ליליאן לרבאט. יהודית ואני נותרנו תחת השגחת סבתא אסטריה — האם היחידה שידעתי. הסבתא מרבאט והדודים מבקרים אותנו פעם בשנה. באים, מביטים, מסתכלים עלינו ובוכים. כשסיימו לבכות, שבים לרבאט עד לשנה הבאה.</p>\n      <h4 class=\"book-sub\">אישה חדשה בבית אבא</h4>\n      <p class=\"book-p\">כשהייתי בת אחת עשרה נישא אבא בשנית לרחל. \"היא תהיה לך אישה מהאגדות\" הבטיח חברו של אבא. וליליאן, אודט ואני \"זכינו\" באם חורגת בדיוק כמו באגדות.</p>\n      <p class=\"book-p\">רחל קיללה אותנו והכתה אותנו מכות רצח. ואבא לא ראה דבר. סבתא פחדה לדבר. דודתי, אחות אמי, הייתה צועקת על רחל: \"לא די שהן יתומות, את גם צריכה להתעלל בהן ככה?!\" אך משהלכה — הייתה רחל מכה אותנו.</p>\n      <p class=\"book-p\">יום אחד רחל השליכה אותי על עריסת ברזל שפגעה לי בזווית העין. אבא ראה את פניי, ואסתר אחותו סיפרה: \"זו אשתך שעשתה את זה!\" אבא סטר לרחל ושלח אותנו לגור אצל אחיו. אך כעבור שבוע עשו שלום בית. כששבנו הביתה היה אבא אדם אחר. אנחנו נעלמנו מעיניו לחלוטין. רחל הייתה למלכה בבית, ואנחנו פחותות מאבק.</p>\n      <p class=\"book-p\">פעם סיפרה רחל לאבא שראתה את ליליאן מדברת עם בחור צעיר. אבא הורה לליליאן לשבת, נטל את כליו מתיקו וגילח את שיער ראשה. בזווית העין ראיתי את רחל עומדת בצד ומחייכת.</p>\n      <h4 class=\"book-sub\">יוצאת לעבוד</h4>\n      <p class=\"book-p\">עבדתי במפעל לרקמה — אבא לקח את כל משכורתי: \"מדי שבוע מסרתי את משכורתך במלואה לאביך, כפי שסוכם מראש!\" אחר כך עברתי לתפור ג׳קטים ושמלות. מהשכר שמרתי קצת בשבילי, וקניתי לי מעט בגדים.</p>\n      <p class=\"book-p\">רחל גנבה חוטי רקמה שקיבלתי מחברתי מרסל. כשראיתי אותה לובשת בגד עם אותם החוטים אמרתי: \"מעניין, החוטים האלה נראים ממש כמו אלה שהיו לי.\" היא הכחישה.</p>\n      <h4 class=\"book-sub\">חיים חדשים באופק</h4>\n      <p class=\"book-p\">מדי יום שישי הייתי הולכת לתנועת הצופים. יום אחד חברה סיפרה שאפשר להירשם לעלייה ארצה. הלכתי למשרד הסוכנות. \"את רוצה לעלות?\" \"כן.\" \"וההורים שלך מסכימים?\" \"להורים שלי לא אכפת ממני.\"</p>\n      <p class=\"book-p\">התארגנתי בלילה. סיפרתי רק לסבתא: \"אני נוסעת לפלשתינה.\" דמעה בצבצה בזווית עינה. כמוני סבתא ידעה, כי מחוץ לבית, בכל מקום, יהיה לי טוב יותר.</p>\n      <p class=\"book-p\">ביום השלישי באו סבתא, ליליאן ורחל להיפרד. אבא לא הגיע. ליליאן הייתה עצובה. רחל ודאי שמחה. ואני? אני שמחתי. השארתי את האומללות מאחוריי, ויצאתי לעבר חיים חדשים. הייתה זו שנת 1950.</p>\n      <h4 class=\"book-sub\">מתחילים את המסע לארץ ישראל</h4>\n      <p class=\"book-p\">עלינו על האנייה \"ג׳ני\" מנמל קזבלנקה למרסיי. שם שמעתי מהרמקולים: \"פרלה כהן לגשת למשרד!\" — אהרון בן הרוש ומרסדס אשתו חיכו לי. הם שכנעו אותי להצטרף אליהם. באותו הרגע החלו חיי החדשים כבת-בית במשפחת בן הרוש.</p>\n      <p class=\"book-p\">דודתי מצרפת הגיעה לחפשני, פינקה אותי וניסתה לשכנע אותי להישאר: \"מה יש לך לחפש בארץ ישראל?\" אך אני גמרתי בדעתי. עזבנו את מרסיי על סיפונה של האנייה \"נגבה\" ב-10 באפריל, והגענו ל\"שער עלייה\" בערב פסח. קיבלנו מרק דלוח, מצה וחתיכת דג מלוח.</p>\n      <p class=\"book-p\">במוצאי החג שב פנחס למושב ומצא את המברק, ובנקודה הזו בדיוק מתחיל סיפורנו המשותף.</p>\n    </div>\n    \n    <div class=\"book-chapter\" id=\"book-ch8\">\n      <h3 class=\"book-ch-title\">פרק ח': בית ומשפחה</h3>\n      <p class=\"book-ch-page\">עמודים 67-76</p>\n      <h4 class=\"book-sub\">איחוד משפחות מרגש</h4>\n      <p class=\"book-p\">ליל הסדר אצל בני משפחתי ברמלה עבר עליי בנעימים, ועם צאת החג שבתי לארבל. שם כבר חיכה לי המברק ששלחו לי אמי ואחיי משער העלייה. להפתעה הנהדרת התלוו מכתב ותמונה. בתמונה זיהיתי את בני משפחתי ולהפתעתי גם את פרלה, שהייתה חברתה של פאני אחותי. התבוננתי בה, ראיתי כמה בגרה ויפתה, ובלי שהבחנתי זרעים ראשונים של אהבה ניטעו בלבי...</p>\n      <p class=\"book-p\">נסעתי לשער העלייה. אימא חיבקה אותי ודמעות שמחה זלגו מעיניה. מאחוריהם ראיתי את פרלה וכבר אז ידעתי שעתיד אחד לנו. הבאתי את אימא, דוד, פאני ופרלה למושב ארבל.</p>\n      <p class=\"book-p\">בצנעה ובעדינות לבלבה האהבה בין פרלה וביני. כאשר ניגשתי אל אימא, היא אמרה: \"בכף שאתה בוחר - בה תאכל כל החיים\". אימא רצתה שאבין שנישואים אינם עניין של מה בכך. \"אם כך, כתוב למואיז אחיך שילך ויבקש את ידה עבורך.\" מואיז ניגש לבית אביה של פרלה וביקש את ידה. זה לא הביע שמץ של התנגדות.</p>\n      <p class=\"book-p\">אך ככל שחלפו הימים, מצב רוחה של אימא הורע. \"מה נהיה ממך? שום סימן יהודי לא נותר בך...\" העובדה שהלכתי גלוי ראש ועסקתי בשחיטה שאינה כשרה, הסבה לה צער. באחד הימים אימא פרצה בבכי ואמרה שאינה יכולה לשאת עוד את החיים במושב. היה ברור לי כי משפחה אחת אנחנו, והבנתי בצער כי ימיי במושב עומדים לפני סיום.</p>\n      <h4 class=\"book-sub\">במעברת תלפיות</h4>\n      <p class=\"book-p\">עזבנו את מושב ארבל ושמנו פנינו לירושלים, למעברת תלפיות שבה התגוררה אחותי סטריה. קיבלתי צריף אחד, ואימא, פרלה ופאני קיבלו צריף אחר. כדי למצוא עבודה הייתי הולך ברגל ללשכת העבודה בבקעה, מרחק קילומטר וחצי. שובצתי בעבודת יציקה בבניין בנייני האומה.</p>\n      <h4 class=\"book-sub\">\"הרי את מקודשת!\"</h4>\n      <p class=\"book-p\">חתונתנו נערכה במעברת תלפיות ב-5 בדצמבר 1951. הרב שלוש ממחנה יהודה עשה את דרכו ברגל עד תלפיות כדי להשיא אותנו. כסף לסעודה לא היה לי, ובצר לי גיסי שלח אותי אל אחיו המושבניק שמילא לי את הקיטבג בפירות, ירקות וכל טוב. אימא, פרלה ונשים נוספות הכינו את הכיבוד לחתונה. לפרלה לא הייתה משפחה בארץ, אך החיבוק החם מבני משפחתי פיצה על כך.</p>\n      <h4 class=\"book-sub\">חייל בצה\"ל</h4>\n      <p class=\"book-p\">זמן קצר לאחר החתונה התגייסתי. שנתיים וחצי שירתתי בבסיס חיל התותחנים בבית-ליד. באחת השבתות הודיעו לי: \"בן הרוש, מזל טוב, נולדה לך בת.\" ביקשתי לראות את אשתי ובתי, אך הרס\"ר אמר: \"אין לך אישור, אתה סמל תורן.\" את פרלה וסימי התינוקת ראיתי רק למחרת. יהודה, בני השני, נולד זמן קצר לאחר שהשתחררתי.</p>\n    </div>\n    \n    <div class=\"book-chapter\" id=\"book-ch9\">\n      <h3 class=\"book-ch-title\">פרק ט': במדים</h3>\n      <p class=\"book-ch-page\">עמודים 77-84</p>\n      <h4 class=\"book-sub\">במשמר הגבול</h4>\n      <p class=\"book-p\">השתחררתי מהצבא בשנת 1954. יום אחד ראיתי שני שוטרים במדים, והתשוקה לשרת במדים עלתה בי. ניגשתי ללשכת הגיוס של המשטרה. \"אני מעוניין להתגייס למשטרה.\" \"למשמר הגבול\" ענה לי הפקיד. רציתי למשטרה הכחולה, אך לא הייתה ברירה.</p>\n      <p class=\"book-p\">שלוש שנים שירתי במשמר הגבול — סיורים רגליים ומארבים ליליים נגד מסתננים. ישנתי בתחנת בית שמש. יצאה הוראה שעובדי משטרה חייבים תעודת סיום בית ספר עממי. שבתי ללמוד, סיימתי בהצלחה, אך כשביקשתי להמשיך — המפקד החדש חסם: \"בן הרוש, לא תהיה פרופסור אצלי.\" ביקשתי לעבור למשטרה הכחולה, ולשמחתי ההעברה אושרה.</p>\n      <h4 class=\"book-sub\">במדי המשטרה הכחולה</h4>\n      <p class=\"book-p\">הוצבתי בתחנת המשטרה שבמגרש הרוסים, במחלקת כוח אדם. עברתי קורס טירונים בשפרעם, קורס קצינים, והתקדמתי עד לניהול מחלקת כוח אדם. לאורך הדרך נתקלתי באפליה עדתית ובמכשולים ביורוקרטיים, אך לא ויתרתי.</p>\n      <p class=\"book-p\">בשנת 1972 נפצע סמי בני קשה בצבא. ביקשתי עזרה מהמפקד — \"מה זה מעניין אותי?\" ענה. פניתי למפקד בכיר יותר שסיפק לי רכב ונהג צמוד לבקר את סמי. המפקד שלי זעם שעקפתי אותו, אך לא הצטערתי לרגע.</p>\n      <h4 class=\"book-sub\">עת מלחמה</h4>\n      <p class=\"book-p\">במלחמת ששת הימים הוצבתי במגרש הרוסים. הובלתי משאית חול לימק\"א תחת אש ירדנית. פגז פגע בעץ שלידנו ורסיסים פגעו גם בי — רסיס באף. עם שחרור ירושלים הוצבתי בגבול ירדן לאפשר מעבר אזרחים אל הכותל.</p>\n      <h4 class=\"book-sub\">סיום תפקידי</h4>\n      <p class=\"book-p\">יום אחד הגיעה מעטפה \"אישי וסודי\" — דרישה להדיח אותי ולמנות אדם אחר. המפקד רצה למנות בן של חברו. לי לא הניחו ללמוד, חסמו את הדרך, ולבסוף זה עלה לי במשרתי. עברתי למטה הארצי, לתחום החבלה ותפיסת מסתננים. עבדתי במשטרה עד סוף 1983. לאורך כל התקופה הרגשתי בקיפוח העדתי, אך אני שמח שהצלחתי לעזור לאנשים רבים.</p>\n    </div>\n    \n    <div class=\"book-chapter\" id=\"book-ch10\">\n      <h3 class=\"book-ch-title\">פרק י': המבט לעבר, הפנים לעתיד</h3>\n      <p class=\"book-ch-page\">עמודים 85-90</p>\n      <h4 class=\"book-sub\">שנים ראשונות בצריף רעוע</h4>\n      <p class=\"book-p\">במעברה שוכנו בצריף מפח. שירותים בחוץ, רחצה בגיגית. אבל פרלה הפכה את הצריף לארמון. על מיטת סימי פרשה כילת טול לבנה עם סרט ורוד. הכביסה שתלתה הבהיקה מלובן והשכנים עמדו והסתכלו כלא מאמינים.</p>\n      <p class=\"book-p\">את יהודה ילדה פרלה כשירושלים הייתה עיר חצויה. עשינו דרכנו ברגל, עוצרים כשהצירים גברו. תפסנו טרמפ להדסה. בשתיים עשרה בלילה הודיעו לי \"מזל טוב, נולד לך בן!\" שכחתי את הארנק, ניגשתי לתחנת משטרה לבקש עזרה — \"זו נראית לך כמו תחנת מוניות?\" ענה השוטר. הלכתי הביתה ברגל. הירדנים ירו, הכלבים נבחו, ואני הלכתי.</p>\n      <h4 class=\"book-sub\">בית משלנו</h4>\n      <p class=\"book-p\">נכנסנו לדירה ברחוב יהודה הנשיא 13 בשכונת הקטמונים. שני חדרים, מקלחת, שירותים ומטבח. בלי תריסים, בלי רשתות, בלי חשמל — אבל היה לנו בית משלנו ושמחנו בחלקנו! בבית הזה נולדו סמי (1956), אילן (1964) ואסף (1974), ובו גדלו כל ילדינו.</p>\n      <p class=\"book-p\">יותר מכול היה חשוב לנו להעניק לילדינו את מה שלא היה לנו, ובעיקר את מה שלא היה לפרלה כילדה: אהבה ותשומת לב. פרלה הקפידה תמיד לבשל את המזון הטוב והבריא ביותר ודאגה שדבר לא יחסר.</p>\n      <h4 class=\"book-sub\">טיול שורשים למרוקו</h4>\n      <p class=\"book-p\">הנסיעה המשמעותית והמרגשת ביותר הייתה למרוקו, לקזבלנקה, אל הרחובות בהם גדלנו, ואל קברי הורינו. את קבר אימה של פרלה לא מצאנו, אך הצלחנו להגיע אל קבריהם של אבי ואחותי. התרגשות עזה אחזה בנו עת אמרנו תפילה על קברם.</p>\n      <h4 class=\"book-sub\">נחת</h4>\n      <p class=\"book-p\">מן הכורסאות הנוחות שבסלון ביתנו בגבעת משואה אנחנו נזכרים בעברנו, וכעת אפשר לחייך. אפשר לחייך כי אחרי כל מה שעברנו טוב לנו, ואנו מלאי שמחה וסיפוק. הצלחנו להקים יחד משפחה לתפארת ולהעניק לילדינו את כל מה שלא היה לנו. יש לנו קשר קרוב וטוב עם כל ילדינו, נכדינו ונינינו.</p>\n      <p class=\"book-p\" style=\"text-align:center;font-style:italic;color:var(--c-gold);margin-top:1.5rem\">\"הדואג לימים — זורע חיטה,<br>הדואג לשנים — נוטע עצים.<br>הדואג לדורות — מחנך אנשים\"<br>(יאנוש קורצ׳אק)</p>\n      <p class=\"book-p\" style=\"text-align:center;font-weight:bold;color:var(--c-gold-l);font-size:1.1rem;margin-top:1rem\">סוף.</p>\n    </div>\n  </div>";
var BOOK_HTML_EN = "<div class=\"book-section\" id=\"book-content\">\n    <h2 class=\"book-main-title\">On the Path of Love from Morocco to Jerusalem</h2>\n    <p class=\"book-subtitle\">Perla & Pinchas Ben-Harrosh | Published: 2014</p>\n    <p class=\"book-p\" style=\"text-align:center;font-style:italic;color:var(--c-gold);font-size:.85rem;margin-bottom:1rem\">שַלַּח לַחְמְךָ עַל־פְּנֵי הַמָּיִם, כי בְּרֹב הַיָּמִים תִּמְצָאֶנּו — קהלת (יא, א)</p>\n    <div class=\"book-nav\" id=\"book-nav\">\n      <button class=\"book-nav-btn active\" onclick=\"document.getElementById('book-prologue').scrollIntoView({behavior:'smooth',block:'start'})\">Prologue</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch1').scrollIntoView({behavior:'smooth',block:'start'})\">Ch.1: Roots in Morocco</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch2').scrollIntoView({behavior:'smooth',block:'start'})\">Ch.2: The Annual Cycle</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch3').scrollIntoView({behavior:'smooth',block:'start'})\">Ch.3: Morocco of My Childhood</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch4').scrollIntoView({behavior:'smooth',block:'start'})\">Ch.4: Zionist Yearning</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch5').scrollIntoView({behavior:'smooth',block:'start'})\">Ch.5: To Freedom</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch6').scrollIntoView({behavior:'smooth',block:'start'})\">Ch.6: First Days</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch7').scrollIntoView({behavior:'smooth',block:'start'})\">Ch.7: Perla's Story</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch8').scrollIntoView({behavior:'smooth',block:'start'})\">Ch.8: Home & Family</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch9').scrollIntoView({behavior:'smooth',block:'start'})\">Ch.9: In Uniform</button>\n      <button class=\"book-nav-btn\" onclick=\"document.getElementById('book-ch10').scrollIntoView({behavior:'smooth',block:'start'})\">Ch.10: Looking Back</button>\n    </div>\n    <div class=\"book-chapter\" id=\"book-prologue\">\n      <h3 class=\"book-ch-title\">Prologue</h3>\n      <p class=\"book-ch-page\">Pages 5-6</p>\n      <p class=\"book-p\">I was a small child then. Mother was home with us, and Father worked several jobs to support the family. In the evenings, Mother would put me and my younger brothers to sleep in our beds, and only later would Father arrive, quietly entering the house. From my bed I would imagine the smile he gave Mother. I could also imagine the light that lit up in her eyes. Then they would sit together at the kitchen table, Mother would serve him dinner, and after he had satisfied his hunger, Father would tell her stories. I would snuggle deep under my blanket and listen. That was the part I waited for.</p>\n      <p class=\"book-p\">\"You know,\" I heard Father say one evening to Mother, \"this vase you are holding is very ancient.\" In my mind's eye I saw Mother standing there with the vase in her hand, perhaps moving it from place to place, or perhaps just lifting it to dust the cabinet beneath it. \"I salvaged it from a shipwreck at sea, long ago, when I worked as an amoudai.\" Years before we were born, Father worked as an amoudai (a kind of diver), for an American company that collected treasures from ships that had sunk at sea.</p>\n      <p class=\"book-p\">\"I don't think I ever told you about the time I almost lost my life there,\" Father said, and I knew that at that moment Mother forgot about the vase, sat down beside him and gazed at him, completely focused. I too, from my bed, was drawn entirely into the story.</p>\n      <p class=\"book-p\">\"היינו יורדים אז למעמקי הים, אל אניות שנטרפו ותרים אחר אוצרות שנותרו בהם. הסתובבנו שם למטה זמן רב, בוחנים את החפצים שטבעו במעמקים, ספונים בין החדרים, מחפשים רק את אלו שהיה בהם ערך\" אבא סיפר והאנייה הלכה והתגלתה לנגד עיניי, על המבנה הגדול והמרשים שלה, קורות העץ המרקיבות מרוב שנים במעמקי הים ולהקות הדגים שהפכו אותה לבית. רטט של עונג ומתח עבר בגבי.</p>\n      <p class=\"book-p\">\"באותו היום,\" המשיך אבא בסיפורו, \"ירדתי אני אל המעמקים. האמודאי שתפקידו היה להוריד אותו מהספינה ולהעלות אותי חזרה, נשאר על מקומו בסיפון. סמכתי עליו שכאשר אסמן לו, הוא ימשכני למעלה. ירדתי בצלילה למטה, בחנתי את שברי הספינה הטרופה שהייתה שקוע בעומק הים, ובחנתי את כל מה שיכול היה להיחשב כאוצרות יקרי ערך. לא רציתי להעלות אתי למעלה חפצים חסרי-ערך ולהיות ללעג וקלס בעיני חברי לעבודה. לפתע הרגשתי שאיני יכול לנשום עוד, וזמן קצר לאחר מכן, מתוך ערפול חושים, הרגשתי איך אני נמשך מן המים מעלה אל הסירה, ומושכב על הסיפון. כשהתאוששתי מעט ניגש אליי הקברניט ואמר לי: 'בן-הרוש, בזמן שהיית בתוך המים, הלך עבדול אל הכבלים שהחזיקו אותך למטה, וכשחשב שאף אחד לא רואה - חתך לך את צינור האוויר. למזלך הוא רק חשב שאף אחד לא ראה אותו, אבל הפועל הקטן שלנו, מחמוד, ראה אותו ורץ אליי להודיע לי, ואני הוריתי לשני אנשים לקפוץ אחריך ולהביא אותך.' ואז, המשיך אבא בסיפורו: 'וכבר אני שומע את הקברניט אומר לי: שנהרוג אותו? ואני נחרדתי כולי, חשבתי שלא שמעתי נכון את דבריו. מה? שאלתי אותו, והקברניט חזר ואמר: עבדול, ניסה לרצוח אותך בזמן שהיית במעמקים! רק תגיד מילה ונהרוג אותו.'\"</p>\n      <p class=\"book-p\">Father paused for a moment, perhaps to breathe, perhaps to wet his throat, and I tensed up in my bed.</p>\n      <p class=\"book-p\">\"I didn't hesitate for a moment and told him: 'No. Dismiss him.'\"</p>\n      <p class=\"book-p\">And again I could breathe. But soon it became clear the story was not yet over.</p>\n      <p class=\"book-p\">\"יום אחד, חודשים מספר לאחר מכן, יצאתי רכוב על סוסי לעבר הנמל, לעבודה. לאחר שיצאתי מן העיר אל המרחבים שבחוץ, זינקו עליי שני ערבים שארבו לי במקום, כיסו את ראשי בשק וקשרו אותי לעץ. חיכיתי שם זמן מה. מרגיש איך החמצן שבשק הולך ואוזל, חרד כי סופי הגיע, וחושב על משפחתי ומי יודיע להוריי על שאירע... ואז שמעתי הלמות פרסות סוסים מרחוק. עד מהרה עצר לידנו מישהו. הוא נותר על הסוס ואני יכולתי להרגיש את מבטיו סורקים אותי מכף רגל ועד ראש. שוביי פנו אליו ואמרו לו 'תפסנו איזה כלב, בן יהודים מלוכלך'. 'לפני שאתם מדברים תורידו את השק, אני רוצה לראות אותו' הוא אמר להם קצרות. השק הוסר מעל ראשי, ואני שוב יכולתי לנשום. אבל עוד בטרם התרגלו עיניי לאור השמש, שמעתי אותו צועק עליהם: 'אתם הכלבים, האיש הזה הציל אותי ממוות, שחררו אותו מיד!'. מצילי היה לא אחר מאותו עבדול, שרק חודשים מספר קודם לכן ניסה להרוג אותי כשהייתי בתוך הים...\"</p>\n      <p class=\"book-p\">Mother must have breathed a sigh of relief then, and so did I, relaxing my small body that had tensed with fear. Father had a wonderful ability to tell stories that held us in suspense until the very last second, and while he spoke I could feel every sensation he described.</p>\n      <p class=\"book-p\">\"שלח לחמך על פני המים כי ברב הימים תמצאנו\" סיכם אז אבא במילותיו של החכם באדם, כותב מגילת קהלת, \"עשה טוב ותמצא טוב.\" ועל אף שאבא לא היה לצדי באותם הרגעים, אלא דיבר עם אימא, הרגשתי איך האהבה, הדאגה וחכמת החיים שלו מרחפות לעברי מבעד לדלת ועוטפות אותי, ושינה מתוקה יורדת עליי.</p>\n      <p class=\"book-p\">Many years have passed since then, but this story continues to accompany me and guide my path. Many times I return in my thoughts to that saying that guided me in Father's ways: \"Do good and you shall find good.\"</p>\n      <p class=\"book-p\">Today, like Father in his time, I dive like an amoudai into the depths of time and space and retrieve from them the treasures of my past; the places where I lived, the people alongside whom I spent my life, and the events that shaped me during my eighty-six years.</p>\n      <p class=\"book-p\">I do this for you, my beloved family — my dear wife and companion, my children, grandchildren and great-grandchildren, so that you too may know where you came from, and so that the path will always shine before you.</p>\n      <p class=\"book-p\" style=\"text-align:left;color:var(--c-gold-d)\">Pinchas Ben-Harrosh, Jerusalem, 2013</p>\n    </div>\n    <div class=\"book-chapter\" id=\"book-ch1\">\n      <h3 class=\"book-ch-title\">Chapter 1: Roots in the Land of Morocco</h3>\n      <p class=\"book-ch-page\">Pages 7-18</p>\n\n      <h4 class=\"book-sub\">Tangier of the Great World</h4>\n      <p class=\"book-p\">שלושה-עשר קילומטרים מפרידים בין ספרד האירופאית ומרוקו הצפון אפריקאית. שלושה-עשר קילומטרים בלבד, טנג׳יר (Tanger), העיר המרכזית באזור, שוכנת בפתחם של מיצרי גיברלטר, בנקודת המפגש שבין הצפון והדרום, הים התיכון והאוקיינוס האטלנטי. עבור מעצמות אירופה הקולוניאליות במאות הקודמות, ובעיקר בעיני שלטונות ספרד הנושקת למרוקו, היה זה פיתוי שאי אפשר לעמוד בפניו, והאזור כולו עבר תהפוכות שלטוניות רבות כאשר פעם שלטו בו הספרדים ופעם האנגלים, פעם הפורטוגזים ופעם הצרפתים. טנג׳יר היפיפייה שאווירה מתירנית שלטה ברחובותיה וחופיה היפים משכו תיירים מכל רחבי אירופה, הייתה במשך מאות שנים מקום ריכוז לדיפלומטים, קונסולים ומרגלים זרים, ושימשה לא אחת כתפאורה לסרטים שאווירה מיוחדת שלטה בהם, ושעסקו במפגש בין המזרח והמערב, טנג׳יר אף הייתה לערש הולדתה של משפחת אמי ומשפחתי שלי.</p>\n\n      <h4 class=\"book-sub\">Mother's Home</h4>\n      <p class=\"book-p\">אמי רינה, הייתה בתם הבכורה של סימי ויהודה קארו והראשונה בין ששת ילדיהם. אחריה נולדו אחיותיה: אסתר, מסודי, לונה ומזלטו, ובסוף, איזקה. הסבא יהודה קארו, המיוחס לRabbi Yosef Karo ומגיע ממשפחת רבנים, היה אדם דתי, אך לא עשה את התורה למרכז עיסוקו, והתפרנס ממסחר בחיטה, שעורה ומזון יבש. לסבא לא היו גידולים משלו, הוא רק סחר בהם. שמו יצא לפניו כסוחר טוב והגון, והוא עשה חיל בעבודתו וראה פרות בעמלו. בבית סבא יהודה וסבתא סימי, שררה רווחה כלכלית. הם התגוררו בבית גדול ומרווח בן שתי קומות, משרתות מקומיות טיפלו בתחזוקת הבית וסייעו לסבתי, שהבית היה מרכז עיסוקה.</p>\n      <p class=\"book-p\">אמא גדלה בטנג׳יר בסביבה מוסלמית-ספרדית, ברחובות שלטה השפה הספרדית. באזורים בהם התגוררו יהודים אפשר היה לשמוע גם את הלדינו היהודית, וזו הייתה שפת האם של אמי.</p>\n\n      <h4 class=\"book-sub\">Rabbi Yosef Karo</h4>\n      <p class=\"book-p\">Rabbi Yosef Karo (1488-1575) הוא מגדולי הרבנים ופוסקי ישראל בכל הדורות, מחבר ה\"שולחן ערוך\" וה\"בית יוסף\", ועסק גם בקבלה. נולד בספרד ונאלץ לנדוד עם הוריו בעקבות גירוש ספרד. עבר מליסבון לקושטא, חי בבית דודו בטורקיה, והתבסס באדריאנופול. בהיותו בן 34 החל בכתיבת חיבורו על הטור. התאלמן, התחתן שוב, והקים ישיבה בניקופול שבבולגריה. עלה לארץ ישראל וקבע מושבו בצפת. לספר הקיצור שסיכם את הלכות ה\"בית יוסף\" קרא \"שולחן ערוך\" — ספר מרכזי ואבן יסוד בהלכה היהודית עד היום.</p>\n      <p class=\"book-p\" style=\"font-size:.8rem;color:rgba(237,224,196,.5)\">Sources: Wikipedia, Daat website</p>\n\n      <h4 class=\"book-sub\">Father's Home</h4>\n      <p class=\"book-p\">אבי, שמואל בן הראש, יליד 1886, גדל גם הוא במרוקו הספרדית, בכפר הדייגים אסילה (Asilah) הסמוך לטנג׳יר. משפחתו של אבא הייתה קטנה מזו של אימא. להוריו, איטו לבית בן-אוליעל ויעקב בן הראש, נולדו שני בנים - שלמה הבכור, שמואל אבי, ושתי בנות - חולה (שם החיבה שלה היה רחל) שנפטרה בספרד בשנת 1947; ואסטריה (אסתר), שבשנת 1947 עזבה את מרוקו, היגרה לברזיל ומשם עקרה לארגנטינה.</p>\n      <p class=\"book-p\">אבא שייך אף הוא לשושלת מכובדת של רבנים, ומיוחס להרא\"ש - רבנו אשר בן-יחיאל, שהיה מגדולי פרשני התלמוד והפוסקים, והייתה לו השפעה מכרעת על עיצוב ההלכה היהודית, ובנו - רבי יעקב בעל הטורים.</p>\n\n      <h4 class=\"book-sub\">The Rosh and His Sons</h4>\n      <p class=\"book-p\">הרא\"ש, הוא רבנו אשר בן יחיאל (1250-1327), נולד בגרמניה. אמו נהרגה על קידוש ה׳ באחת מהגזירות באשכנז. אביו יחיאל שהיה מחסידי אשכנז, היה מחנכו הראשון. למד אצל המהר\"ם מרוטנבורג, ומשזה נאסר, ירש את מקומו בהנהגת וורמס. בשנת 1304 מצא שעת כושר, עזב את גרמניה וברח עם בני ביתו לספרד. הזמינוהו ראשי קהילת טולדו להתיישב בתוכם, להרביץ תורה ולעמוד בראש בית דינם. יצירתו החשובה ביותר היא \"פסקי הרא\"ש\".</p>\n      <p class=\"book-p\">בנו של הרא\"ש הוא רבי יעקב בן-אשר, מכונה \"בעל הטורים\" על שם חיבורו הגדול \"ארבעה טורים\". Rabbi Yosef Karo השקיע שנים רבות ויקרות מחייו בעבודה על חיבור זה.</p>\n      <p class=\"book-p\" style=\"font-size:.8rem;color:rgba(237,224,196,.5)\">Sources: Wikipedia, Daat website</p>\n\n      <h4 class=\"book-sub\">The Fateful Meeting of My Parents</h4>\n      <p class=\"book-p\">אסילה שבמרוקו הספרדית, שוכנת לא רחוק מטנג׳יר, ויהודיה הכירו אלה את אלה. גם משפחת אבי הכירה את משפחת אמי, אך לא היו קשרים של ממש בין שתי המשפחות. הזמן חלף, אמי כבר הגיעה לפרקה, באותה התקופה ובאותו האזור היה גיל שש-עשרה ראוי לנישואין לכל הדעות, ועד מהרה נמצא לה חתן מיועד והשניים התארסו. זמן מה לאחר שהאירוסין כבר היו לעובדה מוגמרת, ובבית אמי החלו להכין את הנדוניה ולהתכונן לחתונה, הגיע אבי לטנג׳יר. באחד הימים, בעת מפגש חברתי או משפחתי, ראה את אמי והתאהב בה.</p>\n      <p class=\"book-p\">הוא ניגש אל סבתא סימי, שהייתה אז אם לחמש בנות ונשאה ברחמה הריון שישי, ואמר לה: \"גברת קארו, אני מבטיח לך שבפעם זאת בן ייוולד לך\". \"מאין אתה יודע זאת?\" התפלאה סבתי, ואבי רק אמר לה: \"אם יתברר שצדקתי - התתני לי את רינה בתך לאישה?\". סבתא הזדעזעה קלות ומחתה: \"אבל רינה כבר מאורסת!\" ואבי רק הוסיף ואמר: \"ובכל זאת...\"</p>\n      <p class=\"book-p\">סבתא כבר כרעה ללדת, ונבואתו של אבי התגשמה. בן נולד לה, דודי איזקה. שמחתה של סבתא סימי לא ידעה גבול ועד מהרה בוטלו האירוסין הקודמים. אמי רינה התארסה עם אבי שמואל, נושא הבשורה המשמחת, ונדמה לי כי אהבה גדולה מזו שהייתה ביניהם - לא יכול היה איש למצוא. אימא קראה לאבא \"מואואנו\" - אהובי, והוא קרא לה בחיבה - \"מיריינה\" (mi reina) - מלכה שלי.</p>\n\n      <h4 class=\"book-sub\">Life in Tangier</h4>\n      <p class=\"book-p\">תושבי טנג׳יר מצאו את פרנסתם במסחר, תיירות ודייג. גם אבי מצא את פרנסתו בים. אבא לא הגביל עצמו למלאכה אחת בלבד ועשה ככל יכולתו על מנת להביא פרנסה טובה הביתה. הוא סחר בחיטה ושעורה, עבד כצבעי, עסק בעבודות-עור, וצלל אל מעמקי הים במסגרת חברה אמריקנית ששלתה אוצרות שאבדו במעמקים. את ביתם קבעו אימא ואבא בטנג׳יר, במבנה מסורתי שבמרכזו חצר, אותו שכרו מבעל בית ערבי. בבית זה נולדו ששת אחיי הגדולים: יעקב (1901), יהודה (1903), משה (1905), מסוד (בעברית יהורם, 1907, נפטר במרוקו בגיל 32 בלבד) ואתי (1911). כולם נולדו בבית בעזרת מיילדת יהודייה בעלת ניסיון רב, כפי שהיה נהוג אז.</p>\n      <p class=\"book-p\">מובן שאיני זוכר דבר מאותה תקופה. טרם נולדתי... אולם ישנם סיפורים שעברו עם השנים במשפחה ואלה נמצאים בקיפולי נפשי ממש כמו זיכרונות אמיתיים. לעתים אני נוטה להתבלבל אם זה משהו שסיפרו לי או משהו שחוויתי. כך או כך, בהיות אחי יהודה פעוט, היה חולני ולא חש בטוב לאורך תקופת מה. אמי שנכבשה בייסורים עזים על חולניותו של יהודה הקטן, התייעצה בשכנותיה ואלה יעצו לה פתרון מוכח ומוצק: ביקור בבית הקברות יעזור לפטור את העולל מהמחלות.</p>\n      <p class=\"book-p\">אימא עשתה כעצת הנשים, ניגשה אל בית הקברות, הניחה את יהודה על הקבר והגתה את שאמרו לה לומר. באותו הרגע, כך סיפרה לי אימא לימים, יצא נחש ירוק מבין הקברים, סבב סביב התינוק אך לא חנק אותו. יהודה שעד זה לא מכבר היה חלוש מכדי להוציא הגה מפיו, נתן קולו בבכי רם. הדבר נראה בעיני אמא כנס והיא בכתה יחד אתו מאושר והקלה.</p>\n\n      <h4 class=\"book-sub\">The White City</h4>\n      <p class=\"book-p\">אחיי הגדולים גדלו ובגרו. יום אחד קיבל אבא מכתב מהשלטונות הספרדיים ששלטו באזור כולו, המבשר כי עם הגיעם לפרקם יגויסו בניו אל הצבא. מבחינת אבא הייתה זו גזירה שאין כל דרך לעמוד בה, ותוך זמן קצר הוא בישר לאימא כי הם עומדים לעזוב את טנג׳יר ולעבוד לקזבלנקה שבמרוקו, שם לא ישיגום ידי השלטון הספרדי.</p>\n      <p class=\"book-p\">זמן קצר אחר-כך, נפרדו הוריי מבני המשפחה, ארזו את חפציהם, נטלו את ששת ילדיהם ועברו לקזבלנקה. משקבעו אימא ואבא את ביתם בקזבלנקה הגיע אליהם מכתב נוסף המתריע על גיוס, הפעם מאת השלטון הצרפתי. אלא שבמרוקו הצרפתית, בשונה מהמצב במרוקו הספרדית, על-אף שהשלטון מגייס נהגו המרוקאים להישאר בביתם לא חשש, ועולם כמנהגו נוהג. באותו יום החליט אבא שמעתה ואילך איננו ספרדים עוד, כי אם מרוקאים, וקזבלנקה היא ביתנו וכך היה. המשפחה נותרה בקזבלנקה.</p>\n      <p class=\"book-p\">בקזבלנקה הביאו הוריי לעולם חמישה ילדים נוספים. רחל נולדה ראשונה (1920, ונפטרה בגיל צעיר, רק בת 18), ושנתיים מאוחר יותר נולד אהרון (1922). בשנת 1923 נולדה אסטריה, אך נפטרה בדמי ימיה, כתינוקת רכה. אחד מאחיי התגעגע אליה געגועים עזים. הוא שב ואמר שהוא \"רוצה אסטריה\" פעמים לאין מספר, ובשנת 1925, כרעה אמי ללדת פעם נוספת. לבת שנולדה קראו אסטריה, כשמה של התינוקת שמתה. ב-20 בדצמבר, שנת 1927, נולדתי אני, פנחס, בן הזקונים של הוריי.</p>\n\n      <h4 class=\"book-sub\">My Sister Fanny</h4>\n      <p class=\"book-p\">עשרה ילדים גידלו וחינכו הוריי, ולא אמרו די. יום אחד הייתה אמי בבית עם העוזרת, ולפתע ראתה מבעד לחלון איש חולף ליד ביתנו, ולצדו צועדת אישה שמחזיקה תינוקת צעירה בידיה. אימא נרעדה. גם העוזרת הבחינה בהם ואמרה לאמא: \"סניורה ריינה, הם הולכים לעבר בית-השעשועים שבסוף הרחוב, הם ודאי מתכוונים למסור שם את התינוקת\". אמי התרגשה ואף מחתה מעינה דמעה.</p>\n      <p class=\"book-p\">אחר ביקשה מהעוזרת לרוץ אחריהם ולקרוא להם להיכנס לביתנו. עד מהרה שבה העוזרת עם בני הזוג והפעוטה. אמא פתחה במסכת שכנועים, אלא שהגבר והאישה שעמדו שם לא היו זקוקים לשכנועים רבים. האישה הצעירה הסתבכה בהיריון מחוץ לנישואים. הייתה זו בושה גדולה בשבילה וכדי לשוב ולחיות בקהילתה היה עליה לוותר על בתה ולעזוב את העיר. אותה אישה הסכימה מיד להשאיר את התינוקת אצל אמי. אימא שלא ידעה קרוא וכתוב, הבינה בפיקחותה שיש לתעד את האירוע כראוי. אחי דוד כתב עבורה מכתב שעליו חתמו האיש והאישה, ובו צוין שהם מוותרים על הילדה והיא נמסרת לאמא מרצונם החופשי. מאז לא ראינו אותם עוד.</p>\n      <p class=\"book-p\">לאחר מכן שלחה אימא את אחותי אסטריה, אל אבא שישב באותה עת בבית-קפה, וביקשה שתגיד לו ש\"אימא לקחה ילדה\". כעבור זמן קצר שבה אסטריה הביתה ובפיה מילים שאבא מסר לה: \"מזל טוב\". בזאת נחתם באופן רשמי האימוץ של הקטנה בבית הוריי.</p>\n      <p class=\"book-p\">פאני, התינוקת שננטשה על ידי אימה הצעירה, גדלה אתנו כאחות לכל דבר. לימים, משנודע לנו דבר אימוצה השביעה אותנו אימא שלא נספר לפאני דבר על-כך, ואנו נשבענו וקיימנו את שבועתנו. רק שנים רבות מאוחר יותר פגשה פאני את בת-דודתי, וזו סיפרה לה על האימוץ. פאני ההמומה נלכדה בסערת רגשות שטלטלה את עולמה. חוסר-אונים ורחמים עצמיים סערו בקרבה, אך בסופו של דבר היא נרגעה והודיעה כי החדשות ששמעה אינן משנות דבר מבחינתה. הוריי הם הוריה, אני, אחיותיי ואחיי הם אחיה, ואת זיכרונות הילדות הטובה שהייתה מנת חלקה, שום דבר לא יוכל לגזול ממנה.</p>\n      <p class=\"book-p\">פאני היא אחותי לכל דבר ודבר, ואנו תמיד היינו המשפחה היחידה שאותה הכירה ואהבה.</p>\n\n      <h4 class=\"book-sub\">Daily Life in the Casablanca of My Childhood</h4>\n      <p class=\"book-p\">בקזבלנקה התגוררנו בבית גדול בן שתי קומות וחמישה חדרים, ברחוב \"הצלב האדום\", רו-דה-לה-קרואה (Rue de la Croix). בקומה הראשונה היו המטבח, השירותים ושני חדרים, ובקומה העליונה היה חדר שירותים נוסף ועוד שלושה חדרי-שינה. אני עדיין יכול לראות את הבית הזה לנגד עיני, אך במיוחד צרוב בזיכרוני מראה הדלת שלו, כמותה לא ראיתי בישראל מעולם. הייתה זו דלת שכדי לפתוח אותה היו מושכים אותה מלמעלה.</p>\n      <p class=\"book-p\">ביתנו היה מחובר לחשמל, וגם מים זורמים היו בו, אך לא תמיד. המים נאגרו על הגגות, משם זרמו אל הצינורות ומהם לברזים. במים האלה התרחצו, כיבסו בגדים ושטפו רצפה, אך לשתייה - לא היו ראויים. את מי השתייה קנו מן הערבי שהיה עובר ברחובות העיר כשהוא נושא עמו נאד גדול של מים.</p>\n      <p class=\"book-p\">מלאכת הכביסה הופקדה בידיה של עוזרת-בית ערבייה, לאחר השפשוף המפרך הייתה תולה את הכביסה על הגג, כפי שהיה נהוג בקזבלנקה. המשרתת הערבייה התגוררה אתנו בבית ואף סעדה על שולחננו. כשאימא הייתה מבשלת - היא הייתה עוזרת לה גם במלאכות המטבח - מקלפת ירקות, שוטפת כלים ועוד, בעוד אימא הייתה יושבת על השרפרף שליד התנור הקטן שעמד במרכז המטבח, משגיחה על הסירים ומלבה את האש במפוח. עבור אימא, שגידלה עשרה ילדים, זו הייתה עזרה שלא תסולא בפז.</p>\n      <p class=\"book-p\">עובד נוסף היה מגיע לביתנו, הוא היה יהודי ונהגנו בו כבן בית, אך לא גר עמנו. מרבית תפקידיו היו בתחום התיקונים והאחזקה בבית, וכל מיני מלאכות שהוריי נזקקו להם. לקראת חג הסוכות היה בונה את הסוכה שלנו, תוך הקפדה על הלכות הסוכה ושמירה על כשרותה.</p>\n      <p class=\"book-p\">נולדתי לבית מלא אחים ואחיות, שופע קולות, מהומה ושאון--ילדים. יום אחד, בעודי תינוק, מתחו אחיי, דוד ומסעוד, חבל בין שני קצוות הבית, עליו כרכו מעין סל עשוי בד, ואותי, הפעוט, הניחו בתוך ערימת הסמרטוטים. אחר הם משכו אותי מעל החבל מצד לצד, ככדור-עף אנושי. כנראה אחיי חשבו שאני מעין צעצוע...</p>\n      <p class=\"book-p\">אבא המשיך תמיד לעסוק בכל העבודות ששימשו לו מקור פרנסה, ודבר לא חסר בבית. הייתי קטן מכדי לחשוב שמשהו מכל זה עומד להשתנות, ובעוד זמן לא רב. לעת עתה הייתה לי ילדות מאושרת בבית גדול, שמח ומלא בבני משפחה אוהבים.</p>\n    </div>\n    \n    <div class=\"book-chapter\" id=\"book-ch2\">\n      <h3 class=\"book-ch-title\">Chapter 2: The Annual Cycle</h3>\n      <p class=\"book-ch-page\">Pages 19-24</p>\n      <h4 class=\"book-sub\">The Taste of Shabbat</h4>\n      <p class=\"book-p\">The days of the year were marked then, as now, by holidays and days of mourning. In our home the holidays were celebrated to the letter, with their prayers, preparations and array of aromas. The Jews of Morocco were all religious and tradition-keeping people. To this day, on Fridays at sunset, when a special atmosphere descends upon Jerusalem, I remember the Shabbat of Casablanca. The Shabbat of my childhood.</p>\n      <p class=\"book-p\">On Shabbat Father was home with us, and Mother would cease her endless housework. We all wore our finest clothes and divided our time between prayers, meals, games and rest.</p>\n      <p class=\"book-p\">One of the hallmarks of Shabbat was the aroma of the cholent, carried like the train of the Shabbat Queen's gown, from the bakery to our home. Mother would prepare the cholent, like all her neighbors, in a deep clay vessel called a tagine. She would stick strips of dough along its rim, giving it a pressure-cooker effect. Since all the Jews placed their cholent pots in the bakery's oven, mistakes sometimes occurred, and more than once another family's cholent arrived at our table. Yet it always had that special taste, the taste of Shabbat.</p>\n      <h4 class=\"book-sub\">The Tishrei Holidays</h4>\n      <p class=\"book-p\">Rosh Hashanah is a holiday that perhaps more than any other heralds a new, clean beginning. Father and my brothers would spend much of the holy day in the synagogue. When I think of Rosh Hashanah at my parents' home, the first image that comes to mind is the large couscous pot accompanied by the rich vegetable soup Mother prepared for the holiday.</p>\n      <p class=\"book-p\">Not a week had passed before Yom Kippur arrived. Days before, my parents would buy roosters and hens for the Kaparot ceremony. A shochet would come to our home, perform the ritual, and slaughter the fowl in our courtyard. We children were then called to help clean the slaughtered chickens and wash the bloodied courtyard.</p>\n      <p class=\"book-p\">We prayed at the synagogue near our home, named after Atadgi, the Sephardi Jew who built it, with enormous chandeliers of gleaming glass cups hanging from its ceiling.</p>\n      <p class=\"book-p\">After Father passed away, when Yom Kippur approached, Mother wept because we had no money to buy fowl for Kaparot. One day we heard noise from the roof. To our great astonishment, as if by order, we found four fowl on the roof with their legs tied. As far as we were concerned, it was nothing short of a miracle.</p>\n      <p class=\"book-p\">After Yom Kippur we would build a sukkah on the roof. During the holiday we could see many sukkot that seemed to have sprouted overnight on the rooftops, marking the Jewish homes like giant mezuzot.</p>\n      <h4 class=\"book-sub\">Days of Feasting and Joy</h4>\n      <p class=\"book-p\">Hanukkah was marked by the oil-wick candles placed in menorahs, and of course the sfenj, the wonderful Moroccan doughnuts Mother would make. Purim was marked by the Megillah reading in the synagogue amid great noise, and the custom of card games we played at home.</p>\n      <h4 class=\"book-sub\">Passover Madness</h4>\n      <p class=\"book-p\">The preparations for Passover, which began almost immediately after Purim, meant for me above all a shrinking of my living space at home. Mother would not let us in without a thorough shaking under her watchful eye, to ensure no chametz crossed the threshold. Day by day we were pushed further from the kitchen until the day before the holiday we found ourselves literally on the doorstep...</p>\n      <p class=\"book-p\">When the holiday began, the entire atmosphere would change. The house was spotless, Mother looked relaxed, and the long table set with the festive Passover dishes heightened our anticipation. Father would read the Haggadah aloud in clear Hebrew, then repeat every passage in Ladino and Moroccan Arabic. The reading lasted three times as long.</p>\n      <h4 class=\"book-sub\">\"Be Prosperous and Dine!\" — The Mimouna</h4>\n      <p class=\"book-p\">Without a doubt the most delightful day was the Mimouna at the end of Passover. In every home women labored over moufletas, alongside countless jams and sweets. A long table was laden with plates of moufletas, honey, milk, jams, abundant dried fruits, almond marzipans. And the crown jewel: a solid sugar cone painted in bright colors.</p>\n      <p class=\"book-p\">Mimouna night was a \"white night.\" Families visited one another, all dressed in traditional holiday clothes, entering with song and the traditional blessing: \"Tirbhu u-tis'adu.\" That night not only Jews visited our homes, but also our Muslim neighbors. It was a night of bringing hearts together, of brotherhood regardless of religion or race.</p>\n      <p class=\"book-p\">The next morning the French authorities would provide buses for the Jews, and we would travel to nature, usually by the sea, where we held picnics, grilled meat, played darbukas, sang Moroccan songs and celebrated endlessly.</p>\n      <h4 class=\"book-sub\">The White Holiday — Shavuot</h4>\n      <p class=\"book-p\">Shavuot was marked by two main features. The first was the \"Meldado\" — a night of study, when men studied Torah all night in the synagogue. As a small child, I too waited for the day I would be allowed to study with Father and stay up all night like the grown-ups. The second was the array of cheeses. My aunt Ada would make cheeses herself and bring them to us before the holiday.</p>\n      <h4 class=\"book-sub\">Lamentations of Tisha B'Av</h4>\n      <p class=\"book-p\">The central holidays of the year were sealed by the day of mourning of Tisha B'Av. Mother would weep and sob for hours. The day on which the Jewish people remember their calamities, foremost the destruction of the Temple, was for her a reminder of every loss in her family. I remember myself as a small child approaching Mother and trying to comfort her, and Mother trying to control her emotions for a moment, only to break down sobbing again shortly after.</p>\n    </div>\n    \n    <div class=\"book-chapter\" id=\"book-ch3\">\n      <h3 class=\"book-ch-title\">Chapter 3: The Morocco of My Childhood</h3>\n      <p class=\"book-ch-page\">Pages 25-34</p>\n      <h4 class=\"book-sub\">Childhood</h4>\n      <p class=\"book-p\">My earliest memories are filled with the colors, sounds and scents of \"Rue de la Croix\" — the street where I was born and raised. When I took my first steps in the world, four of my brothers were already married. In the large, beautiful house my parents rented from a wealthy Arab, five children remained. My world was safe and peaceful, and as a curious, uninhibited child I explored my surroundings.</p>\n      <p class=\"book-p\">I loved joining Mother on her trips to the Jewish market. The colors and aromas that rose from every direction thrilled me. We could find everything there — fruits, vegetables, pickles, spices, dry goods. Every day a peddler would pass through the street with two goats, bells tied around their necks announcing their arrival. When Mother heard the bells she would come out with a container, and the peddler would fill it straight from the goat's udders. We lacked for nothing.</p>\n      <h4 class=\"book-sub\">Other Lives</h4>\n      <p class=\"book-p\">Mother, burdened by raising children and maintaining the house, sent me to a kindergarten at the Spanish church. In that Christian kindergarten I saw for the first time a life completely different from everything I knew. The nuns taught us songs in Spanish, and the priest would visit, moving from child to child, with some children kissing the large cross hanging from his neck. But deep inside I knew this was not my place as a Jew.</p>\n      <h4 class=\"book-sub\">School Days</h4>\n      <p class=\"book-p\">My parents enrolled me in a school from the Alliance Israelite Universelle network, a Jewish cultural organization. Every morning I wore the uniform — a black smock with a white collar. One hour a week was dedicated to Hebrew, while all other subjects were secular: math, reading, history, geography, English.</p>\n      <p class=\"book-p\">School was not easy for me. I struggled with reading and writing. Among my classmates were children from wealthy families who had private tutors, while I had no one. Father worked from morning to night, Mother could not read or write, and my older brothers were too busy. Once the teacher ordered us to memorize a passage. I stood before the class with trembling legs and sealed lips, unable to utter a word. The teacher prepared his whip and gave me forty lashes on my palms. I returned to my seat bruised and tearful.</p>\n      <p class=\"book-p\">One day a friend whose heart went out to me suggested: \"Pinchas, before class take some garlic cloves, crush them and rub them well into your palms. If you do this, the teacher's blows won't hurt.\" And so I did. That day the teacher's lashes truly didn't hurt, and he was astonished at the calm with which I received them. From then on he left me alone.</p>\n      <p class=\"book-p\">Only one person refused to accept this fate: my dear mother. She saw my suffering and bruised hands, and her heart ached. Her friends suggested a tried remedy: \"On Friday, after you remove the dough from the bowl and braid challahs for Shabbat, fill the bowl with water, and the white water that remains — pour into a clean glass and give Pinchas to drink.\" Mother did so, and to everyone's surprise — from that day on I began to succeed in school.</p>\n      <h4 class=\"book-sub\">The Magic of the Silver Screen</h4>\n      <p class=\"book-p\">From a young age I loved going to the cinema. My brother's friend stood at the entrance and let me in free: Tarzan, Mickey Mouse, and other American films. One day, instead of school, I headed to the cinema. It was a wonderful day! But the teacher noticed my absence and sent a note to Mother. Father, who instantly understood that his darling boy was also lying, gave me thirty-six lashes with a dry whip, counting them with the verse: \"And He, being merciful, shall forgive iniquity...\"</p>\n      <h4 class=\"book-sub\">In a Foreign Land</h4>\n      <p class=\"book-p\">\"Sajif.\" Dirty Jew. That's what the Christians of Casablanca called us, and the Muslims followed suit. As children we felt fear; we could smell the hatred in the streets. It erupted especially on Fridays after prayer and the imams' sermons. My poor mother was once struck with an iron bar by a blind Muslim, simply because he realized she wasn't Muslim. That day Mother came home crying.</p>\n      <p class=\"book-p\">No one spoke then of immigration to the Land of Israel. Everything we knew about it came from the French press, where the country was called \"Palestine.\" Only in the synagogue could one speak freely.</p>\n      <h4 class=\"book-sub\">The End of Childhood</h4>\n      <p class=\"book-p\">Father could not stop smoking, and at a relatively young age fell gravely ill with lung disease. In his final days he barely left his bed and Mother cared for him. I was free to do as I wished, and what drew me was the neighbors' bag shop. My first wages were just a few coins. I went to the grocery and bought candles and matches. When I came home I handed them to Mother without a word, and tears welled in her eyes.</p>\n      <p class=\"book-p\">In late 1939, I stood beside Mother in the kitchen as she kneaded dough for Shabbat challahs. Suddenly a tremendous explosion shook our home. A French ship loaded with explosives had blown up in Casablanca's port. Father was not killed outright, but the blast that hurled him from his bed to the ceiling and back caused irreversible internal damage. Within days he began vomiting blood, and three or four days later — on the 26th of Cheshvan, November 1939 — he returned his soul to his Creator.</p>\n      <p class=\"book-p\">I was forced to grow up in an instant. I was only eleven years old, and so that I could say Kaddish at the grave I was declared bar mitzvah. The tallit that would normally have been draped over me during the Torah reading, I wore for the first time over the fresh grave, and in a choked voice, through tear-blurred eyes, I joined the Kaddish.</p>\n      <p class=\"book-p\">Shortly afterward, before finishing eighth grade, I left school.</p>\n    </div>\n    \n    <div class=\"book-chapter\" id=\"book-ch4\">\n      <h3 class=\"book-ch-title\">Chapter 4: Zionist Yearning</h3>\n      <p class=\"book-ch-page\">Pages 35-42</p>\n      <h4 class=\"book-sub\">After Father's Death</h4>\n      <p class=\"book-p\">The bar mitzvah ceremony held over Father's grave sealed my childhood. Mother showered me with love, but she could not read or write and could not follow my studies. Father, who had watched over me while alive, was no more.</p>\n      <p class=\"book-p\">Father was thin but strong, strict yet warm and loving. I remember his figure in his djellaba, and when I was cold he would tuck me inside it, embrace me and warm me. His death was a heavy blow to the family.</p>\n      <h4 class=\"book-sub\">My First Job</h4>\n      <p class=\"book-p\">After Father died I left school before finishing eighth grade and worked at a bag and wallet factory. The owner was Arab, the workers were Arabs and Jews. I started with cleaning but learned to cut and sew bags and work with different leathers — horse hide, lioness skin and more. By thirteen and a half I was a small independent contractor.</p>\n      <h4 class=\"book-sub\">Far From Here — World War II</h4>\n      <p class=\"book-p\">The war broke out when I was twelve. We knew about the armies' advances, but about the camps we knew nothing. We first heard of the horrors from the few refugees who managed to flee Poland and reach Casablanca.</p>\n      <h4 class=\"book-sub\">In the Youth Movement</h4>\n      <p class=\"book-p\">At fifteen I joined the Zionist youth movement HaPoel HaMizrachi. We held assemblies, learned about Zionism, heard about the Land of Israel and the detention camps in Cyprus. I learned to play accordion from Professor Bringola, an Italian. One day, selling the Jewish newspaper \"Le Juive\" on a street corner, the Professor bought a copy and smiled. I was so proud to sell \"The Jewish Voice\" to a Christian man.</p>\n      <h4 class=\"book-sub\">Family Visit to Asilah</h4>\n      <p class=\"book-p\">Before the Tishrei holidays I traveled to Asilah, Father's birthplace. At the border they removed me from the bus — no visa. A relative's husband who worked for the railway helped me get through by train. In Asilah I spoke at the synagogue about Zionism, showed them the blue-and-white emblem, and on Sunday took them to the fields to learn to work the land, sing \"Hava Nagila\" and dance the Hora.</p>\n      <h4 class=\"book-sub\">My Heart is in the East</h4>\n      <p class=\"book-p\">Zionism consumed me completely. I understood that Jews have no place in the world except in the Land of Israel. One thought accompanied me: I want to go to the Land of Israel and die with a weapon in my hand, if necessary. The idea of aliyah took root in my heart and I knew my days in Morocco were numbered.</p>\n    </div>\n    \n    <div class=\"book-chapter\" id=\"book-ch5\">\n      <h3 class=\"book-ch-title\">Chapter 5: To Freedom</h3>\n      <p class=\"book-ch-page\">Pages 43-50</p>\n      <h4 class=\"book-sub\">In the Youth Movement</h4>\n      <p class=\"book-p\">I was fifteen and a half when I understood my future was not in Casablanca. A friend said: \"If you join the Dror movement they'll send you to Israel immediately.\" Without hesitation I left HaPoel HaMizrachi and joined Dror. All I wanted was to reach the Land of Israel — I didn't care how or with whom.</p>\n      <h4 class=\"book-sub\">Training Camp</h4>\n      <p class=\"book-p\">The training camp was held near the Morocco-Algeria border for about two weeks. We learned hand-to-hand combat with sticks, knives and pistols. We trained with weapons — disassembly, assembly, cleaning, loading, kneeling and aiming. Only we never actually fired.</p>\n      <h4 class=\"book-sub\">Setting Out Illegally</h4>\n      <p class=\"book-p\">We were divided into cells of four and given forged passports. The route to the Algerian border passed along the coast; we went disguised as vacationers. At four in the morning we moved toward the border and boarded a bus to Algeria. In Oujda we saw Jewish women in mourning — dozens of Jews had been massacred there on June 7, 1948. The story strengthened my resolve to fight for my country as a proud Jew.</p>\n      <h4 class=\"book-sub\">Training in France</h4>\n      <p class=\"book-p\">From Marseille we were brought to a palace at Château Mont Bardo, where an agricultural training farm had been established. I raised rabbits and worked in vineyards. When I asked for water, the French farmers laughed: \"In our vineyards we don't drink water\" — and poured me red wine. After three months we heard radio reports of Independence War battles and casualties. We decided pastoral life in France was enough, and even went on a hunger strike.</p>\n      <h4 class=\"book-sub\">On the Ship</h4>\n      <p class=\"book-p\">In July 1948 we boarded the \"Saint Antonio,\" originally a fishing vessel, with about four hundred people. We slept in the hold, eight to a cabin, where fish had been stored. As young people full of vision and joy, we would burst into enthusiastic song and dance the Hora on deck.</p>\n      <p class=\"book-p\">Finally, late at night, we saw the lights of Haifa from the deck. For a moment our breath was taken away with excitement. Then we all burst into singing Hatikvah. When we reached Haifa, we descended to the shore, fell to the ground and kissed the earth of the Land.</p>\n    </div>\n    \n    \n    <div class=\"book-chapter\" id=\"book-ch6\">\n      <h3 class=\"book-ch-title\">Chapter 6: First Days in the Land</h3>\n      <p class=\"book-ch-page\">Pages 51-56</p>\n      <h4 class=\"book-sub\">\"No Shoes — No Training!\"</h4>\n      <p class=\"book-p\">I set foot on the Land of Israel for the first time on November 11, 1948, and I was overjoyed. Minutes after we fell to the ground and kissed the earth, we broke into a stormy Hora. Then we entered the Jewish Agency offices and were \"treated\" to a dose of DDT spray, head to toe.</p>\n      <p class=\"book-p\">Lists were drawn up. No one asked us anything, no one explained. Married men were sent to transit camps; single men — straight to the army! Minutes after disembarking, I was on a bus from Haifa to Beit Lid.</p>\n      <p class=\"book-p\">We used the little Hebrew we knew for our first strike in Israel. We all stood singing to the commander: \"No shoes — no training!\" He blushed to the roots of his hair.</p>\n      <p class=\"book-p\">We were given old patched British army uniforms and civilian shoes. Our commander arrived wearing tall, gleaming red military boots. The discrimination against new immigrants was unbearable.</p>\n      <p class=\"book-p\">Just before the camouflage-netted bus left for the front, my name was called. \"I have a letter from the Dror movement — you're going to Kibbutz Regavim.\" My first military service ended in that moment.</p>\n      <h4 class=\"book-sub\">Equal and More Equal — Beit Oren</h4>\n      <p class=\"book-p\">We were sent to Kibbutz Regavim in the Negev, then transferred to Beit Oren. I was assigned as a cowherd, going out to pasture each morning breathing the clear Carmel air.</p>\n      <p class=\"book-p\">After a minor hand surgery, I was immediately assigned to work. \"If you don't return to work immediately — there's no place for you here!\" the work coordinator said coldly. My friends declared solidarity. When the instructor called us \"lazy,\" I lost my composure. Yitzhak Tabenkin himself came to speak with us, but even he toed the same line. In the end we all left the kibbutz.</p>\n      <h4 class=\"book-sub\">Pardes Hanna</h4>\n      <p class=\"book-p\">We moved to a transit camp in Pardes Hanna. The days dragged on and I felt suffocated. I once found a donkey, rode it to the market playing my flute, and sold it for a lira and a half. Its owner may still be looking for it...</p>\n      <p class=\"book-p\">Finally word came: Moshav Arbel, a young settlement near Kfar Hittin. \"Ben-Harrosh, we'll drive you there — check if it suits our group.\"</p>\n      <h4 class=\"book-sub\">Moshav Arbel</h4>\n      <p class=\"book-p\">I started working in the cowshed and sheepfold. I loved shepherding the flock of four hundred, taking my flute each day. Every sheep had a name. Esti, the spotted ewe who led the flock, was the most beautiful and mischievous. I learned that when I see a snake, I must freeze and wait for it to pass.</p>\n      <h4 class=\"book-sub\">The Arbel Disaster</h4>\n      <p class=\"book-p\">On July 20, 1950, we saw heavy smoke rising from the Swedish hut. Half served as the infants' house. Strong winds from Tiberias turned a lit wick into a blaze. The nursemaid opened the door for help, but the wind fanned the fire. All the infants burned alive, including the nursemaid's own daughter. That day Moshav Arbel's cemetery was established. The babies were the first to be buried there.</p>\n      <p class=\"book-p\">I loved life at Moshav Arbel and saw my future there. But fate had other plans. Before long everything changed completely.</p>\n    </div>\n    <div class=\"book-chapter\" id=\"book-ch7\">\n      <h3 class=\"book-ch-title\">Chapter 7: Perla's Story</h3>\n      <p class=\"book-ch-page\">Pages 57-66</p>\n      <h4 class=\"book-sub\">My Distant Childhood</h4>\n      <p class=\"book-p\">Casablanca for me is a place that blends my emotions between sadness and sorrow, between moments of grief and sparks of joy. It is where my life began.</p>\n      <p class=\"book-p\">My mother, Simi Bouzaglo, was born in 1908 in Larache, Spanish Morocco. Grandmother was called Rachma. Mother grew up in a prosperous home with many siblings. The family moved to Rabat. At school in Casablanca she met my father, Yitzhak Isaac Cohen. They married at seventeen — young, beautiful and in love.</p>\n      <p class=\"book-p\">Father became a barber and opened his own successful shop. Three daughters were born: Lillian (1932), me (1933), and Odette (1934). But three months after Odette's birth, Mother fell ill with pneumonia, contracted tuberculosis, and in 1936, at just 26, she died.</p>\n      <h4 class=\"book-sub\">Orphanhood</h4>\n      <p class=\"book-p\">I was barely two. I remember nothing of those days. Grandmother Rachma took Lillian to Rabat. Odette and I remained with Grandmother Asteria — the only mother I ever knew. The grandmother from Rabat and the uncles visited once a year. They would come, look at us, and cry. When they finished crying, they returned to Rabat until the following year.</p>\n      <h4 class=\"book-sub\">A New Woman in Father's House</h4>\n      <p class=\"book-p\">When I was eleven, Father remarried Rachel. \"She'll be a wife from fairy tales,\" his friend promised. And we three \"earned\" a stepmother exactly like in fairy tales.</p>\n      <p class=\"book-p\">Rachel cursed and beat us mercilessly. Father saw nothing. Grandmother was afraid to speak. My aunt would shout: \"Aren't they orphans enough — must you abuse them too?!\" But after she left, Rachel would beat us.</p>\n      <p class=\"book-p\">One day Rachel threw me against an iron crib that struck my eye. Father saw my face; his sister Esther confessed: \"Your wife did this!\" He slapped Rachel and sent us to his brother's house. But a week later they reconciled. When we returned, Father was a different person. We had vanished from his eyes completely. Rachel was queen; we were less than dust.</p>\n      <p class=\"book-p\">Once Rachel told Father she saw Lillian talking to a young man. Without a word, Father sat Lillian down, took out his tools and shaved her head. In the corner of my eye I saw Rachel standing aside, smiling.</p>\n      <h4 class=\"book-sub\">Going to Work</h4>\n      <p class=\"book-p\">I worked at an embroidery factory — Father took all my wages. Later I sewed jackets and dresses, keeping a little for myself. Rachel stole embroidery threads my friend gave me. When I saw her wearing a garment with those threads, she denied everything.</p>\n      <h4 class=\"book-sub\">New Horizons</h4>\n      <p class=\"book-p\">Every Friday I went to the Scouts. One day a friend said I could register for aliyah. At the Jewish Agency: \"Do you want to go?\" \"Yes.\" \"Do your parents agree?\" \"My parents don't care about me.\"</p>\n      <p class=\"book-p\">I packed at night. Told only Grandmother: \"I'm going to Palestine.\" A tear glistened in her eye. She knew, as I did, that anywhere outside that house would be better for me.</p>\n      <p class=\"book-p\">On the third day, Grandmother, Lillian and Rachel came to say goodbye. Father didn't come. Lillian was sad. Rachel was surely glad. And me? I was happy. I left the misery behind. It was 1950.</p>\n      <h4 class=\"book-sub\">The Journey to the Land of Israel</h4>\n      <p class=\"book-p\">We sailed on the \"Jenny\" from Casablanca to Marseille. There I heard over the loudspeakers: \"Perla Cohen, report to the office!\" — Aharon Ben-Harrosh and his wife Mercedes were waiting. They convinced me to join them. That moment my new life as part of the Ben-Harrosh family began.</p>\n      <p class=\"book-p\">My aunt from France found me, pampered me and tried to convince me to stay: \"What do you have to look for in Israel?\" But my mind was made up. We left Marseille on the \"Negba\" on April 10, arriving at \"Sha'ar Aliyah\" on Passover eve. We received thin soup, matzah and salted fish.</p>\n      <p class=\"book-p\">After the holiday, Pinchas returned to the moshav and found the telegram. And at that exact point, our shared story begins.</p>\n    </div>\n    \n    <div class=\"book-chapter\" id=\"book-ch8\">\n      <h3 class=\"book-ch-title\">Chapter 8: Home and Family</h3>\n      <p class=\"book-ch-page\">Pages 67-76</p>\n      <h4 class=\"book-sub\">A Moving Family Reunion</h4>\n      <p class=\"book-p\">After Passover I returned to Arbel and found a telegram from my mother and siblings at Sha'ar Aliyah. With it came a letter and a photograph. In the photo I recognized my family and, to my surprise, Perla — my sister Fanny's friend. I looked at her, saw how she had blossomed, and without realizing it, the first seeds of love were planted in my heart...</p>\n      <p class=\"book-p\">I drove to Sha'ar Aliyah. Mother embraced me with tears of joy. Behind them I saw Perla, and already then I knew we shared one future. When I told Mother, she said wisely: \"The spoon you choose — you'll eat with it for life.\" I wrote to my brother Moiz in Casablanca, who went to Perla's father and asked for her hand. He showed not a trace of objection.</p>\n      <p class=\"book-p\">But Mother grew unhappy at the moshav. One day she wept and said she could bear it no longer. I understood that we are one family, and my days at the moshav were ending.</p>\n      <h4 class=\"book-sub\">Talpiot Transit Camp</h4>\n      <p class=\"book-p\">We left Arbel for Jerusalem's Talpiot transit camp, near my sister Asteria. I walked daily to the labor office and was assigned to pour concrete at Binyanei HaUma.</p>\n      <h4 class=\"book-sub\">\"You Are Hereby Sanctified!\"</h4>\n      <p class=\"book-p\">Our wedding was held at Talpiot on December 5, 1951. Rabbi Shalosh walked from Mahane Yehuda to marry us. My brother-in-law's brother filled my kitbag with fruits and vegetables. Mother, Perla and the women prepared the feast.</p>\n      <h4 class=\"book-sub\">Soldier in the IDF</h4>\n      <p class=\"book-p\">Shortly after the wedding I was drafted. Two and a half years in the Artillery Corps at Beit Lid. One Shabbat I was told: \"Congratulations, you have a daughter!\" I asked to see my wife and baby, but the sergeant said: \"No permission — you're duty sergeant.\" I saw Perla and baby Simi only the next day.</p>\n    </div>\n    \n    <div class=\"book-chapter\" id=\"book-ch9\">\n      <h3 class=\"book-ch-title\">Chapter 9: In Uniform</h3>\n      <p class=\"book-ch-page\">Pages 77-84</p>\n      <h4 class=\"book-sub\">Border Police</h4>\n      <p class=\"book-p\">Discharged in 1954, I saw two policemen in uniform and felt the calling. I joined the Border Police, serving three years — foot patrols and night ambushes against infiltrators at Beit Shemesh. When ordered to obtain a school certificate, I studied and succeeded, but a new commander blocked further education: \"You won't be a professor under me.\" I transferred to the Blue Police.</p>\n      <h4 class=\"book-sub\">Blue Police</h4>\n      <p class=\"book-p\">Posted at the Russian Compound, I worked in HR, completed officers' course, and eventually managed the department. When my son Sami was badly injured in the army in 1972, my commander refused to help. I went over his head to a senior officer who provided a car and driver around the clock.</p>\n      <h4 class=\"book-sub\">Wartime</h4>\n      <p class=\"book-p\">During the Six-Day War, I drove a sand truck to the YMCA under Jordanian fire. Shrapnel hit my nose. After the liberation of Jerusalem, I was posted at the border to enable civilians to reach the Western Wall.</p>\n      <h4 class=\"book-sub\">End of Service</h4>\n      <p class=\"book-p\">One day an \"personal and confidential\" envelope arrived — a demand to replace me. They had never let me study, blocked my path, and in the end it cost me my position. I transferred to national headquarters, working in infiltration prevention. I served until the end of 1983. Throughout, I felt ethnic discrimination, yet I'm grateful for the opportunity and proud I helped many people.</p>\n    </div>\n    \n    <div class=\"book-chapter\" id=\"book-ch10\">\n      <h3 class=\"book-ch-title\">Chapter 10: Looking Back, Facing the Future</h3>\n      <p class=\"book-ch-page\">Pages 85-90</p>\n      <h4 class=\"book-sub\">Early Years in a Tin Shack</h4>\n      <p class=\"book-p\">At the transit camp we lived in a tin shack. No indoor plumbing, bathing in a tub. But Perla turned our shack into a palace. Over baby Simi's cot she draped a white tulle canopy with a pink ribbon. Her laundry gleamed so white the neighbors stared in disbelief.</p>\n      <p class=\"book-p\">When Yehuda was born, Jerusalem was a divided city. We walked to the main road through contractions, caught a ride to Hadassah. At midnight: \"Congratulations, a son!\" I'd forgotten my wallet. At the nearby police station I asked for help — \"Does this look like a taxi stand?\" the officer replied. I walked home on foot. The Jordanians fired, the dogs barked, and I walked.</p>\n      <h4 class=\"book-sub\">A Home of Our Own</h4>\n      <p class=\"book-p\">We moved to 13 Yehuda HaNasi Street in the Katamon neighborhood. Two rooms, shower, toilet and kitchen. No shutters, no screens, no electricity — but it was our home and we were happy! There Sami (1956), Ilan (1964) and Asaf (1974) were born, and all our children grew up.</p>\n      <p class=\"book-p\">Above all, we wanted to give our children what we never had — especially what Perla never had as a child: love and attention. Perla always cooked the best, healthiest food and ensured nothing was lacking.</p>\n      <h4 class=\"book-sub\">A Roots Trip to Morocco</h4>\n      <p class=\"book-p\">The most meaningful journey was to Morocco, to Casablanca, to the streets where we grew up, and to our parents' graves. We couldn't find Perla's mother's grave, but we reached my father's and sister's graves. Profound emotion seized us as we prayed over them.</p>\n      <h4 class=\"book-sub\">Contentment</h4>\n      <p class=\"book-p\">From the comfortable armchairs in our Givat Massuah home, we look back and can smile. We can smile because after everything we've been through, life is good, and we are filled with joy and fulfillment. We succeeded in building a magnificent family together and giving our children everything we never had.</p>\n      <p class=\"book-p\" style=\"text-align:center;font-style:italic;color:var(--c-gold);margin-top:1.5rem\">\"He who plans for days — sows wheat,<br>He who plans for years — plants trees.<br>He who plans for generations — educates people.\"<br>(Janusz Korczak)</p>\n      <p class=\"book-p\" style=\"text-align:center;font-weight:bold;color:var(--c-gold-l);font-size:1.1rem;margin-top:1rem\">The End.</p>\n    </div>\n  </div>";
